test("component asset pseudo images use a stable layer key when a whole-layer match has no shape id", () => {
  const pseudoImages = componentAssetLayerPseudoImages(0, {
    layersByPage: new Map([[0, [{
      layerKey: "0:diagram-zone",
      box: { x: 100, y: 120, w: 420, h: 180 },
      detector: "structured-case-graphic-underlay-crop",
      layerType: "diagram-zone",
      templateFamily: "hub-spoke",
      strategyMode: "preserve-crop-with-component-reference",
      readiness: { status: "applied-plugin-motif-ready" },
      localAssets: []
    }]]])
  });

  assert.equal(pseudoImages.length, 1);
  assert.equal(pseudoImages[0].id, "0:diagram-zone");
  assert.equal(pseudoImages[0].source.componentAssetLayerKey, "0:diagram-zone");
});
