test("native rebuild selects only source-native rich slides for direct preservation", () => {
  const workDir = fs.mkdtempSync(path.join(os.tmpdir(), "native-slide-preservation-"));
  const reportsDir = path.join(workDir, "reports");
  fs.mkdirSync(reportsDir, { recursive: true });
  fs.writeFileSync(path.join(reportsDir, "source-editability-report.json"), JSON.stringify({
    slides: [
      { pageIndex: 0, classification: "native-rich" },
      { pageIndex: 1, classification: "image-only" },
      { pageIndex: 2, classification: "mixed" },
      { pageIndex: 3, classification: "native-rich" }
    ]
  }));

  assert.deepEqual([...sourceNativeSlideIndexes(workDir)], [0, 3]);
});

test("quality profile counts source-native passthrough slides as editable structure", () => {
  const profile = summarizeEditabilityProfile({
    ir: {
      slideSize: { widthPt: 100, heightPt: 100 },
      pages: [{
        pageIndex: 0,
        preserveTemplateSlide: true,
        source: {
          detector: "source-native-slide-passthrough",
          nativeObjects: 3,
          textRuns: 8
        },
        images: [], textBoxes: [], shapes: [], tables: [], charts: [], icons: []
      }]
    },
    raster: { pages: [] }
  });

  assert.equal(profile.editableObjects, 3);
  assert.equal(profile.sourceNativePassthroughPages, 1);
  assert.equal(profile.sourceNativePassthroughObjects, 3);
  assert.equal(profile.sourceNativePassthroughTextRuns, 8);
});

test("native rebuild normalizes image layer metadata for downstream component strategy", () => {
  const image = normalizeImageLayerMetadata({
    id: "crop-1",
    source: {
      detector: "foreground-graphic-underlay-crop",
      expressionForm: "table-or-matrix",
      expressionSubtype: "table-grid",
      recommendedAction: "rebuild-native-table-grid-when-cells-are-axis-aligned",
      layer: { layerType: "table-zone" }
    }
  });

  assert.equal(image.layerType, "table-zone");
  assert.equal(image.detector, "foreground-graphic-underlay-crop");
  assert.equal(image.expressionForm, "table-or-matrix");
  assert.equal(image.expressionSubtype, "table-grid");
  assert.equal(image.recommendedAction, "rebuild-native-table-grid-when-cells-are-axis-aligned");
});

test("horizontal step chain fill sampling uses source colors and retains a safe fallback", () => {
  const sourceImage = makeImage(960, 540, "#FFFFFF");
  fillRect(sourceImage, 140, 140, 120, 80, "#1C5FAD");
  fillRect(sourceImage, 300, 140, 120, 80, "#2CAB67");

  const blue = sampleHorizontalStepChainFill(sourceImage, { x: 140, y: 140, w: 120, h: 80 }, { widthPt: 960, heightPt: 540 }, "#236DAD", "blue");
  const green = sampleHorizontalStepChainFill(sourceImage, { x: 300, y: 140, w: 120, h: 80 }, { widthPt: 960, heightPt: 540 }, "#2DBB63", "green");
  const fallback = sampleHorizontalStepChainFill(null, { x: 0, y: 0, w: 80, h: 40 }, { widthPt: 960, heightPt: 540 }, "#236DAD", "blue");

  assert.equal(blue, "#1C5FAD");
  assert.equal(green, "#2CAB67");
  assert.equal(fallback, "#236DAD");
});

test("native rebuild lets refreshed source metadata override stale top-level image metadata", () => {
  const image = normalizeImageLayerMetadata({
    id: "debugger-window",
    layerType: "diagram-zone",
    expressionForm: "complex-diagram",
    expressionSubtype: "top-complex-diagram",
    recommendedAction: "preserve-fidelity-crop-until-subtype-rebuilder-is-confident",
    source: {
      detector: "top-complex-diagram-crop",
      expressionForm: "screenshot-or-document",
      expressionSubtype: "debugger-window-screenshot",
      recommendedAction: "keep-local-crop-and-overlay-external-text-only",
      layer: { layerType: "diagram-zone", recommendedAction: "preserve-local-crop" }
    }
  });

  assert.equal(image.expressionForm, "screenshot-or-document");
  assert.equal(image.expressionSubtype, "debugger-window-screenshot");
  assert.equal(image.recommendedAction, "keep-local-crop-and-overlay-external-text-only");
});

test("native rebuild normalizes final preserved crop strategies", () => {
  const page = {
    images: [{
      id: "document-version-sketch-residual",
      type: "fidelity-crop",
      box: { x: 64, y: 180, w: 454, h: 249 },
      source: {
        detector: "document-version-sketch-residual-crop",
        layerType: "illustration-zone",
        expressionForm: "icon-or-illustration",
        expressionSubtype: "illustration",
        nonEditableReason: "left sticky/sketch illustration preserved after native document-version folder flow reconstruction",
        componentRenderStrategy: { mode: "plugin-component-template" },
        componentTemplateGroupApplied: false,
        componentTemplateNativeShapes: 0
      }
    }, {
      id: "asset-os-flow-icon",
      type: "fidelity-crop",
      box: { x: 120, y: 140, w: 70, h: 70 },
      source: {
        detector: "asset-os-flow-icon-crop",
        expressionForm: "icon-or-illustration",
        expressionSubtype: "asset-os-flow-icon",
        nonEditableReason: "complex Asset OS gem/shield icon preserved as a local crop while surrounding flow structure is rebuilt natively"
      }
    }, {
      id: "real-template",
      type: "fidelity-crop",
      source: {
        detector: "component-template-source",
        componentTemplateGroupApplied: true,
        componentTemplateNativeShapes: 4,
        componentRenderStrategy: { mode: "plugin-component-template" }
      }
    }, {
      id: "native-graphic-1-sketch-residual",
      type: "fidelity-crop",
      source: {
        detector: "document-version-sketch-residual-crop",
        expressionForm: "icon-or-illustration",
        expressionSubtype: "illustration",
        nonEditableReason: "left sticky/sketch illustration preserved after native document-version folder flow reconstruction",
        componentTemplateGroupApplied: true,
        componentTemplateNativeShapes: 2,
        componentTemplateCropReplacedByNative: false,
        componentTemplateCropReplacementReason: "component-template-source-layer-requires-fidelity-crop",
        componentRenderStrategy: { mode: "plugin-component-template" }
      }
    }, {
      id: "missing-template-illustration",
      type: "fidelity-crop",
      source: {
        detector: "two-panel-diagram-crop",
        expressionForm: "icon-or-illustration",
        expressionSubtype: "illustration",
        nonEditableReason: "component candidate group was unavailable, so local crop remains the fidelity source",
        componentTemplateGroupApplied: true,
        componentTemplateNativeShapes: 0,
        componentTemplateCropReplacedByNative: false,
        componentTemplateCropReplacementReason: "component-template-group-not-found",
        componentRenderStrategy: { mode: "plugin-component-template" }
      }
    }],
    shapes: [{
      id: "suppressed-template-node",
      type: "rect",
      source: {
        detector: "plugin-component-template-native-shape",
        componentTemplateGroupApplied: true,
        componentTemplatePart: "process-node",
        layerSourceId: "native-graphic-1"
      }
    }, {
      id: "kept-template-node",
      type: "rect",
      source: {
        detector: "plugin-component-template-native-shape",
        componentTemplateGroupApplied: true,
        componentTemplatePart: "process-node",
        layerSourceId: "real-template"
      }
    }]
  };

  normalizePageImageMetadata(page);

  assert.equal(page.images[0].source.componentRenderStrategy.mode, "preserve-local-crop");
  assert.equal(page.images[0].source.componentTemplateGroupApplied, undefined);
  assert.equal(page.images[0].source.componentTemplateNativeShapes, undefined);
  assert.equal(page.images[1].source.componentRenderStrategy.mode, "preserve-local-crop");
  assert.equal(page.images[1].source.componentRenderStrategy.editableExpectation, "standalone-visual-asset-preserved-as-movable-crop");
  assert.equal(page.images[2].source.componentRenderStrategy.mode, "plugin-component-template");
  assert.equal(page.images[2].source.componentTemplateGroupApplied, true);
  assert.equal(page.images[3].source.componentRenderStrategy.mode, "preserve-local-crop");
  assert.equal(page.images[3].source.componentTemplateGroupApplied, undefined);
  assert.equal(page.images[4].source.componentRenderStrategy.mode, "preserve-local-crop");
  assert.equal(page.images[4].source.componentTemplateGroupApplied, undefined);
  assert.deepEqual(page.shapes.map((shape) => shape.id), ["kept-template-node"]);
});

