test("quality gate can fail when component template crops remain retained", () => {
  const componentTemplateCropStatus = {
    retainedImages: 2,
    actionableRetainedImages: 1
  };

  const defaultGate = summarizeQualityGateStatus({
    summary: { rejected: 0 },
    componentTemplateCropStatus
  });
  assert.equal(defaultGate.passed, true);
  assert.equal(defaultGate.retainedComponentTemplateCrops, 2);

  const strictGate = summarizeQualityGateStatus({
    summary: { rejected: 0 },
    componentTemplateCropStatus,
    requireNoRetainedComponentTemplateCrops: true
  });
  assert.equal(strictGate.passed, false);
  assert.ok(strictGate.failures.includes("component-template-retained-crops"));
  assert.equal(strictGate.requireNoRetainedComponentTemplateCrops, true);

  const actionableGate = summarizeQualityGateStatus({
    summary: { rejected: 0 },
    componentTemplateCropStatus,
    requireNoActionableRetainedComponentTemplateCrops: true
  });
  assert.equal(actionableGate.passed, false);
  assert.ok(actionableGate.failures.includes("actionable-component-template-retained-crops"));
  assert.equal(actionableGate.actionableRetainedComponentTemplateCrops, 1);
});

test("quality gate allows protected retained component template crops in actionable mode", () => {
  const gate = summarizeQualityGateStatus({
    summary: { rejected: 0 },
    componentTemplateCropStatus: {
      retainedImages: 2,
      protectedRetainedImages: 2,
      actionableRetainedImages: 0
    },
    requireNoActionableRetainedComponentTemplateCrops: true
  });

  assert.equal(gate.passed, true);
  assert.equal(gate.retainedComponentTemplateCrops, 2);
  assert.equal(gate.actionableRetainedComponentTemplateCrops, 0);
});

