test("resolvePptxBuildMode enables OpenXML batch generation explicitly", () => {
  assert.equal(resolvePptxBuildMode({}).engine, "python");
  assert.equal(resolvePptxBuildMode({ "pptx-engine": "openxml" }).engine, "openxml");
  assert.equal(resolvePptxBuildMode({ "openxml-batch": "true" }).engine, "openxml");
  assert.equal(resolvePptxBuildMode({ pptxEngine: "dotnet" }).engine, "openxml");
  assert.equal(resolvePptxBuildMode({ "pptx-engine": "openxml" }).powerPointSafe, true);
  assert.equal(resolvePptxBuildMode({ "powerpoint-safe": "false" }).powerPointSafe, false);
});

test("OpenXML delivery runs the PowerPoint repair gate unless explicitly disabled", () => {
  const openXml = resolvePptxBuildMode({ "pptx-engine": "openxml" });
  assert.equal(shouldRunPowerPointOpenGate({}, openXml), true);
  assert.equal(shouldRunPowerPointOpenGate({ "powerpoint-open-gate": "false" }, openXml), false);
  assert.equal(shouldRunPowerPointOpenGate({ "powerpoint-open-gate": "true" }, resolvePptxBuildMode({})), true);
  assert.equal(shouldRunPowerPointOpenGate({}, resolvePptxBuildMode({})), false);
});

