test("normalizePptxBuildJobs validates IR and PPTX output boundaries", () => {
  assert.deepEqual(normalizePptxBuildJobs([]), []);
  assert.throws(() => normalizePptxBuildJobs([{ irFile: "deck.json" }]), /requires irFile and outFile/);
  const jobs = normalizePptxBuildJobs([{ irFile: "deck.json", outFile: "deck.pptx", tag: "keep" }]);
  assert.equal(jobs.length, 1);
  assert.equal(jobs[0].tag, "keep");
  assert.equal(path.isAbsolute(jobs[0].irFile), true);
  assert.equal(path.isAbsolute(jobs[0].outFile), true);
});

test("buildPptxBatch can build multiple native editable PPTX files through OpenXML", { timeout: 60_000 }, () => {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "native-rebuild-openxml-batch-"));
  const firstIr = path.join(tmp, "first.ir.json");
  const secondIr = path.join(tmp, "second.ir.json");
  const firstPptx = path.join(tmp, "first.pptx");
  const secondPptx = path.join(tmp, "second.pptx");
  fs.writeFileSync(firstIr, `${JSON.stringify(createOpenXmlBatchSmokeIr("Native Batch One"), null, 2)}\n`, "utf8");
  fs.writeFileSync(secondIr, `${JSON.stringify(createOpenXmlBatchSmokeIr("Native Batch Two"), null, 2)}\n`, "utf8");

  buildPptxBatch([
    { irFile: firstIr, outFile: firstPptx },
    { irFile: secondIr, outFile: secondPptx }
  ], { "pptx-engine": "openxml" });

  const firstSlideXml = readZipEntry(firstPptx, "ppt/slides/slide1.xml").toString("utf8");
  assert.match(firstSlideXml, /Native Batch One/);
  assert.match(firstSlideXml, /<p:grpSp>/);
  assert.match(readZipEntry(secondPptx, "ppt/slides/slide1.xml").toString("utf8"), /Native Batch Two/);
});

function createOpenXmlBatchSmokeIr(text) {
  return {
    version: "1.0",
    slideSize: { widthPt: 960, heightPt: 540 },
    pages: [{
      pageIndex: 0,
      sourceImage: "",
      background: { fill: "#FFFFFF" },
      shapes: [{
        id: "card",
        type: "roundrect",
        box: { x: 100, y: 90, w: 280, h: 90 },
        style: { fill: "#EAF2FF", stroke: "#4472C4", strokeWidth: 1 },
        source: { nativeComponentGroupId: "batch-card" }
      }],
      textBoxes: [{
        id: "label",
        text,
        box: { x: 120, y: 115, w: 240, h: 32 },
        font: { family: "Arial", sizePt: 18, weight: "bold", color: "#1F1F1F", align: "center", valign: "mid", lineHeightMultiple: 1 },
        style: {},
        source: { nativeComponentGroupId: "batch-card" }
      }],
      images: [],
      tables: [],
      charts: []
    }]
  };
}

