test("createVisualAtomNativeShapes promotes matrix solid arrow residuals to editable right arrows", () => {
  const visualAtoms = [];
  for (let index = 0; index < 8; index += 1) {
    visualAtoms.push({
      id: `grid-${index}`,
      kind: "grid-line-candidate",
      shapeHint: index % 2 === 0 ? "grid-line-vertical" : "grid-line-horizontal",
      box: index % 2 === 0
        ? { x: 60 + index * 22, y: 80, w: 2, h: 180 }
        : { x: 42, y: 94 + index * 20, w: 260, h: 2 },
      color: "#9CB1C6",
      density: 0.82,
      nativeCandidate: true,
      residualCandidate: false
    });
  }
  visualAtoms.push({
    id: "green-flow-arrow",
    kind: "icon-crop-candidate",
    shapeHint: "complex",
    box: { x: 180, y: 118, w: 100, h: 52 },
    color: "#22B164",
    density: 0.52,
    areaRatio: 0.022,
    nativeCandidate: false,
    residualCandidate: true
  });
  const image = {
    id: "matrix-underlay",
    box: { x: 0, y: 0, w: 500, h: 320 },
    source: {
      detector: "foreground-graphic-underlay-crop",
      layer: {
        layerType: "table-zone",
        diagramUnderstanding: {
          archetype: "matrix-or-grid",
          confidence: 0.92,
          nodeCount: 8,
          nodes: Array.from({ length: 8 }, (_, index) => ({
            id: `node-${index}`,
            box: { x: 80 + index * 10, y: 90, w: 42, h: 18 }
          })),
          visualAtoms
        }
      }
    }
  };

  const shapes = createVisualAtomNativeShapes([image]);
  const arrow = shapes.find((shape) => shape.source.detector === "visual-atom-native-right-arrow");

  assert.ok(arrow);
  assert.equal(arrow.type, "rightArrow");
  assert.equal(arrow.source.atomKind, "native-right-arrow-candidate");
  assert.equal(arrow.source.promotedFrom, "icon-crop-candidate");
  const promotedAtom = image.source.layer.diagramUnderstanding.visualAtoms.find((atom) => atom.id === "green-flow-arrow");
  assert.equal(promotedAtom.kind, "native-right-arrow-candidate");
  assert.equal(promotedAtom.residualCandidate, false);
  assert.equal(image.source.layer.diagramUnderstanding.visualAtomKindCounts["native-right-arrow-candidate"], 1);
});

test("detectDenseLinkedNodeAtoms separates nodes when connectors merge components", () => {
  const image = {
    width: 360,
    height: 220,
    rgba: Buffer.alloc(360 * 220 * 4, 255)
  };
  const paint = (x, y, w, h, color = [18, 108, 180]) => {
    for (let yy = y; yy < y + h; yy += 1) {
      for (let xx = x; xx < x + w; xx += 1) {
        const offset = (yy * image.width + xx) * 4;
        image.rgba[offset] = color[0];
        image.rgba[offset + 1] = color[1];
        image.rgba[offset + 2] = color[2];
        image.rgba[offset + 3] = 255;
      }
    }
  };
  [[70, 45], [145, 45], [220, 45], [70, 125], [145, 125], [220, 125]].forEach(([x, y]) => paint(x, y, 22, 22));
  paint(92, 55, 53, 5);
  paint(167, 55, 53, 5);
  paint(92, 135, 53, 5);
  paint(167, 135, 53, 5);
  paint(80, 67, 5, 58);
  paint(155, 67, 5, 58);
  paint(230, 67, 5, 58);

  const atoms = detectDenseLinkedNodeAtoms(image, { x: 0, y: 0, w: 360, h: 220 }, { widthPt: 360, heightPt: 220 }, {
    targetColor: "#126CB4",
    colorTolerance: 80,
    minConnectedNodes: 8,
    maxNodes: 10
  });

  assert.ok(atoms.length >= 6);
  assert.equal(atoms.every((atom) => atom.source?.sourceImageDetected === true), true);
  assert.equal(atoms.every((atom) => atom.nativeCandidate === true), true);
});

test("extractVisualAtoms augments sparse linked diagrams with dense node atoms", () => {
  const image = {
    width: 360,
    height: 220,
    rgba: Buffer.alloc(360 * 220 * 4, 255)
  };
  const paint = (x, y, w, h, color = [18, 108, 180]) => {
    for (let yy = y; yy < y + h; yy += 1) {
      for (let xx = x; xx < x + w; xx += 1) {
        const offset = (yy * image.width + xx) * 4;
        image.rgba[offset] = color[0];
        image.rgba[offset + 1] = color[1];
        image.rgba[offset + 2] = color[2];
        image.rgba[offset + 3] = 255;
      }
    }
  };
  [[70, 45], [145, 45], [220, 45], [70, 125], [145, 125], [220, 125]].forEach(([x, y]) => paint(x, y, 22, 22));
  paint(92, 55, 128, 5);
  paint(92, 135, 128, 5);
  paint(80, 67, 5, 58);
  paint(155, 67, 5, 58);
  paint(230, 67, 5, 58);

  const atoms = extractVisualAtoms(image, { x: 0, y: 0, w: 360, h: 220 }, { widthPt: 360, heightPt: 220 }, {
    maxAtoms: 40,
    enableDenseLinkedNodes: true
  });
  const denseNodes = atoms.filter((atom) => atom.source?.detector === "dense-linked-node-visual-atom");

  assert.ok(denseNodes.length >= 6);
  assert.equal(denseNodes.every((atom) => atom.kind === "native-rect-candidate"), true);
  assert.equal(denseNodes.every((atom) => atom.nativeCandidate === true), true);
});

test("extractVisualAtoms keeps dense linked node augmentation opt-in", () => {
  const image = {
    width: 240,
    height: 120,
    rgba: Buffer.alloc(240 * 120 * 4, 255)
  };
  const paint = (x, y, w, h) => {
    for (let yy = y; yy < y + h; yy += 1) {
      for (let xx = x; xx < x + w; xx += 1) {
        const offset = (yy * image.width + xx) * 4;
        image.rgba[offset] = 18;
        image.rgba[offset + 1] = 108;
        image.rgba[offset + 2] = 180;
        image.rgba[offset + 3] = 255;
      }
    }
  };
  [[32, 28], [82, 28], [132, 28], [32, 72], [82, 72], [132, 72]].forEach(([x, y]) => paint(x, y, 18, 18));
  paint(50, 36, 100, 4);
  paint(50, 80, 100, 4);

  const atoms = extractVisualAtoms(image, { x: 0, y: 0, w: 240, h: 120 }, { widthPt: 240, heightPt: 120 }, {
    maxAtoms: 40
  });

  assert.equal(atoms.some((atom) => atom.source?.detector === "dense-linked-node-visual-atom"), false);
});

