test("createVisualAtomNativeShapes infers fallback arrow topology between native nodes", () => {
  const sourceImage = makeImage(520, 300, "#FFFFFF");
  fillRect(sourceImage, 44, 96, 72, 48, "#2F80ED");
  fillRect(sourceImage, 308, 96, 72, 48, "#2F80ED");
  fillRect(sourceImage, 128, 118, 150, 6, "#21AA63");
  fillRightTriangle(sourceImage, 282, 107, 24, 28, "#21AA63");
  const image = {
    id: "pixel-arrow-topology-layer",
    box: { x: 0, y: 0, w: 420, h: 240 },
    source: {
      detector: "product-screenshot-overlay",
      componentRenderStrategy: {
        mode: "preserve-crop-with-native-overlays",
        implementationMode: "hybrid-native-overlay"
      },
      layer: {
        layerType: "screenshot-zone",
        recommendedAction: "split-native-with-residual-crop",
        diagramUnderstanding: {
          nativeReadiness: "hybrid-native-plus-residual-crops",
          confidence: 0.7
        }
      }
    }
  };

  const shapes = createVisualAtomNativeShapes([image], sourceImage, { widthPt: 520, heightPt: 300 });
  const nodes = shapes.filter((shape) => shape.source.detector === "visual-atom-native-rect");
  const arrow = shapes.find((shape) => shape.source.atomKind === "connector-arrow-candidate");

  assert.equal(nodes.length, 2);
  assert.ok(arrow);
  assert.equal(arrow.style.endArrow, "triangle");
  assert.ok(arrow.source.fromAtomId);
  assert.ok(arrow.source.toAtomId);
  assert.notEqual(arrow.source.fromAtomId, arrow.source.toAtomId);
  assert.ok(nodes.some((shape) => shape.source.atomId === arrow.source.fromAtomId));
  assert.ok(nodes.some((shape) => shape.source.atomId === arrow.source.toAtomId));
});

test("createVisualAtomNativeShapes infers fallback container hierarchy around nodes", () => {
  const sourceImage = makeImage(540, 320, "#FFFFFF");
  fillRect(sourceImage, 34, 70, 360, 130, "#DDEBFF");
  fillRect(sourceImage, 64, 106, 72, 48, "#2F80ED");
  fillRect(sourceImage, 286, 106, 72, 48, "#2F80ED");
  fillRect(sourceImage, 148, 128, 110, 6, "#21AA63");
  fillRightTriangle(sourceImage, 262, 117, 24, 28, "#21AA63");
  const image = {
    id: "pixel-container-topology-layer",
    box: { x: 0, y: 0, w: 432, h: 256 },
    source: {
      detector: "product-screenshot-overlay",
      componentRenderStrategy: {
        mode: "preserve-crop-with-native-overlays",
        implementationMode: "hybrid-native-overlay"
      },
      layer: {
        layerType: "screenshot-zone",
        recommendedAction: "split-native-with-residual-crop",
        diagramUnderstanding: {
          nativeReadiness: "hybrid-native-plus-residual-crops",
          confidence: 0.72
        }
      }
    }
  };

  const shapes = createVisualAtomNativeShapes([image], sourceImage, { widthPt: 540, heightPt: 320 });
  const rects = shapes.filter((shape) => shape.source.detector === "visual-atom-native-rect");
  const container = rects.find((shape) => shape.source.topologyRole === "container");
  const children = rects.filter((shape) => shape.source.containerAtomId === container?.source.atomId);
  const arrow = shapes.find((shape) => shape.source.atomKind === "connector-arrow-candidate");

  assert.ok(container);
  assert.equal(children.length, 2);
  assert.deepEqual(new Set(container.source.containedAtomIds), new Set(children.map((shape) => shape.source.atomId)));
  assert.ok(arrow);
  assert.ok(children.some((shape) => shape.source.atomId === arrow.source.fromAtomId));
  assert.ok(children.some((shape) => shape.source.atomId === arrow.source.toAtomId));
});

test("createVisualAtomNativeShapes allows safe line diagram atom overlays when plugin template is unavailable", () => {
  const visualAtoms = [];
  for (let index = 0; index < 12; index += 1) {
    visualAtoms.push({
      id: `grid-v-${index}`,
      kind: "grid-line-candidate",
      shapeHint: "grid-line-vertical",
      axis: "v",
      box: { x: 40 + index * 18, y: 80, w: index % 3 === 0 ? 9 : 3, h: 180 },
      color: index % 3 === 0 ? "#4685c9" : "#a8d4c5",
      nativeCandidate: true,
      residualCandidate: false,
      density: index % 3 === 0 ? 0.72 : 0.5
    });
  }
  const shapes = createVisualAtomNativeShapes([{
    id: "line-diagram-layer",
    box: { x: 30, y: 80, w: 420, h: 220 },
    source: {
      detector: "line-diagram-graphic-underlay-crop",
      componentRenderStrategy: {
        mode: "plugin-component-template",
        implementationMode: "auth-or-download-required",
        applicationPlan: { requiresDownload: true },
        bestCandidate: { downloadable: false }
      },
      layer: {
        layerType: "diagram-zone",
        recommendedAction: "preserve-local-crop",
        diagramUnderstanding: {
          archetype: "unclassified-diagram",
          confidence: 0.62,
          nativeReadiness: "preserve-crop-with-structured-metadata",
          visualAtoms,
          visualAtomKindCounts: { "grid-line-candidate": visualAtoms.length },
          evidence: { detector: "line-diagram-graphic-underlay-crop" }
        }
      }
    }
  }]);

  assert.ok(shapes.length > 0);
  assert.ok(shapes.length <= 12);
  assert.ok(shapes.every((shape) => shape.source.detector === "visual-atom-native-connector"));
  assert.ok(shapes.every((shape) => shape.source.layerSourceId === "line-diagram-layer"));
  assert.equal(new Set(shapes.map((shape) => shape.source.atomId)).size, shapes.length);
});

