test("fully native visual atom layers drop erased residual images", () => {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "slideclone-native-atom-drop-"));
  const sourceImage = makeImage(420, 220, "#FFFFFF");
  fillRect(sourceImage, 70, 82, 80, 44, "#2F80ED");
  fillRect(sourceImage, 170, 101, 60, 6, "#2F80ED");
  fillRect(sourceImage, 250, 82, 80, 44, "#27AE60");
  fillRect(sourceImage, 290, 126, 6, 34, "#27AE60");
  fillRect(sourceImage, 250, 160, 80, 36, "#F2994A");
  const assetPath = path.join(tempDir, "native-atom-residual.png");
  writePng(assetPath, cropPng(sourceImage, { x: 50, y: 40, w: 320, h: 160 }));
  const image = {
    id: "fully-native-atom-layer",
    assetPath,
    box: { x: 50, y: 40, w: 320, h: 160 },
    source: {
      layer: {
        layerType: "diagram-zone",
        recommendedAction: "attempt-native-reconstruction",
        diagramUnderstanding: {
          archetype: "flow-card-chain",
          confidence: 0.86,
          nativeReadiness: "native-rebuild",
          nodeCount: 0,
          visualNodeCount: 3,
          visualConnectorCount: 2,
          visualAtoms: [
            { id: "atom-a", kind: "native-rect-candidate", shapeHint: "rect", box: { x: 70, y: 82, w: 80, h: 44 }, color: "#2F80ED", nativeCandidate: true, residualCandidate: false, density: 0.9 },
            { id: "atom-ab", kind: "connector-line-candidate", box: { x: 170, y: 101, w: 60, h: 6 }, color: "#2F80ED", nativeCandidate: true, residualCandidate: false, density: 0.95 },
            { id: "atom-b", kind: "native-rect-candidate", shapeHint: "rect", box: { x: 250, y: 82, w: 80, h: 44 }, color: "#27AE60", nativeCandidate: true, residualCandidate: false, density: 0.9 },
            { id: "atom-bc", kind: "connector-line-candidate", box: { x: 290, y: 126, w: 6, h: 34 }, color: "#27AE60", nativeCandidate: true, residualCandidate: false, density: 0.95 },
            { id: "atom-c", kind: "native-rect-candidate", shapeHint: "rect", box: { x: 250, y: 160, w: 80, h: 36 }, color: "#F2994A", nativeCandidate: true, residualCandidate: false, density: 0.9 }
          ]
        }
      }
    }
  };

  const shapes = createVisualAtomNativeShapes([image]);
  assert.equal(image.source.visualAtomFullyObjectified, true);
  assert.equal(image.source.dropErasedResidualAfterNativeRebuild, true);

  eraseObjectifiedLayerPrimitives({
    page: { images: [image] },
    sourceImage,
    textBoxes: [],
    primitiveShapes: shapes,
    slideSize: { widthPt: 420, heightPt: 220 },
    irDir: tempDir
  });
  const page = { images: [image] };
  splitErasedResidualCrops({ page, irDir: tempDir });

  assert.equal(page.images.length, 0);
});

