test("createStickyNoteClusterShapes rebuilds colored sticky-note blocks as native shapes", () => {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "slideclone-sticky-note-"));
  const sourceImage = makeImage(960, 540, "#FFFFFF");
  fillRect(sourceImage, 95, 150, 145, 86, "#F39A28");
  fillRect(sourceImage, 270, 205, 150, 92, "#B4B5B8");
  fillRect(sourceImage, 445, 145, 156, 96, "#F29B2A");
  fillRect(sourceImage, 610, 250, 145, 90, "#B2B4B7");
  fillRect(sourceImage, 120, 128, 220, 10, "#707070");
  fillRect(sourceImage, 500, 120, 150, 10, "#777777");
  fillRect(sourceImage, 700, 145, 14, 150, "#777777");
  const assetPath = path.join(tempDir, "sticky-crop.png");
  writePng(assetPath, cropPng(sourceImage, { x: 60, y: 110, w: 740, h: 270 }));
  const image = {
    id: "sticky-cluster-layer",
    assetPath,
    box: { x: 60, y: 110, w: 740, h: 270 },
    source: {
      detector: "foreground-graphic-crop",
      layer: {
        layerType: "diagram-zone",
        diagramUnderstanding: {
          archetype: "flow-card-chain",
          confidence: 0.78
        }
      }
    }
  };

  const shapes = createStickyNoteClusterShapes([image], sourceImage, { widthPt: 960, heightPt: 540 });

  assert.equal(shapes.length, 4);
  assert.ok(shapes.every((shape) => shape.type === "rect"));
  assert.ok(shapes.every((shape) => shape.source.detector === "sticky-note-cluster-native-note"));
  assert.deepEqual(new Set(shapes.map((shape) => shape.source.colorFamily)), new Set(["orange", "gray"]));
  assert.equal(image.source.stickyNoteClusterObjectified, true);
  assert.equal(image.source.objectifiedStickyNotes, 4);

  eraseObjectifiedLayerPrimitives({
    page: { images: [image] },
    sourceImage,
    textBoxes: [],
    primitiveShapes: shapes,
    slideSize: { widthPt: 960, heightPt: 540 },
    irDir: tempDir
  });

  const erased = readPng(assetPath);
  const sampleOffset = ((150 - 110 + 18) * erased.width + (95 - 60 + 18)) * 4;
  assert.ok(erased.rgba[sampleOffset] > 235);
  assert.ok(erased.rgba[sampleOffset + 1] > 235);
  assert.ok(erased.rgba[sampleOffset + 2] > 235);
  assert.equal(image.source.primitiveErased, true);

  const split = splitErasedResidualCrop(image, tempDir);
  assert.ok(split.length >= 2);
  assert.ok(split.every((item) => item.source.detector === "sticky-note-sketch-residual-crop"));
  assert.ok(split.every((item) => item.source.residualSplitMode === "sticky-note-sketch-fragment"));
  assert.ok(split.every((item) => item.box.w * item.box.h < image.box.w * image.box.h * 0.35));
});

test("sticky-note sketch splitting stays inside the detected sticky-note region", () => {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "slideclone-sticky-region-"));
  const sourceImage = makeImage(960, 540, "#FFFFFF");
  fillRect(sourceImage, 95, 150, 145, 86, "#F39A28");
  fillRect(sourceImage, 265, 195, 135, 86, "#B4B5B8");
  fillRect(sourceImage, 120, 305, 155, 86, "#F29B2A");
  fillRect(sourceImage, 118, 126, 210, 10, "#707070");
  fillRect(sourceImage, 450, 145, 210, 115, "#276FBC");
  fillRect(sourceImage, 610, 315, 170, 86, "#45BD89");
  const assetPath = path.join(tempDir, "mixed-crop.png");
  writePng(assetPath, cropPng(sourceImage, { x: 60, y: 110, w: 760, h: 330 }));
  const image = {
    id: "mixed-sticky-and-folder",
    assetPath,
    box: { x: 60, y: 110, w: 760, h: 330 },
    source: {
      detector: "foreground-graphic-crop",
      layer: {
        layerType: "diagram-zone",
        recommendedAction: "split-native-with-residual-crop",
        diagramUnderstanding: {
          archetype: "flow-card-chain",
          confidence: 0.8
        }
      }
    }
  };

  const shapes = createStickyNoteClusterShapes([image], sourceImage, { widthPt: 960, heightPt: 540 });
  assert.equal(shapes.length, 3);
  assert.ok(image.source.stickyNoteClusterRegionBox);
  eraseObjectifiedLayerPrimitives({
    page: { images: [image] },
    sourceImage,
    textBoxes: [],
    primitiveShapes: shapes,
    slideSize: { widthPt: 960, heightPt: 540 },
    irDir: tempDir
  });

  const split = splitErasedResidualCrop(image, tempDir);
  assert.ok(split.length >= 1);
  assert.ok(split.some((item) => item.source.detector === "sticky-note-sketch-residual-crop"));
  assert.ok(split.some((item) => item.source.detector === "sticky-note-adjacent-residual-crop"));
  assert.ok(split
    .filter((item) => item.source.detector === "sticky-note-sketch-residual-crop")
    .every((item) => item.box.x + item.box.w < 430));
  assert.ok(split
    .filter((item) => item.source.detector === "sticky-note-adjacent-residual-crop")
    .every((item) => item.box.x > 430));
});

