test("asset hub cycle underlay rebuilds structure while preserving all endpoint icons as minimum-unit crops by default", () => {
  const page = {
    textBoxes: [
      { text: "构建企业级AI原生产品资产中枢", box: { x: 238, y: 53, w: 480, h: 27 } }
    ],
    images: [
      {
        id: "native-graphic-underlay",
        type: "fidelity-crop",
        box: { x: 65.6, y: 91.5, w: 819.43, h: 367.5 },
        source: {
          detector: "cycle-illustration-underlay-crop",
          layer: { layerType: "illustration-zone" }
        }
      }
    ]
  };

  const objects = createAssetHubCycleIllustrationObjects(page, { widthPt: 960, heightPt: 540 });

  assert.equal(objects.shapes.some((shape) => shape.source.detector === "asset-hub-cycle-native-shield"), false);
  assert.equal(objects.shapes.filter((shape) => shape.source.detector === "asset-hub-cycle-native-connector").length >= 10, true);
  assert.equal(objects.shapes.filter((shape) => shape.source.detector === "asset-hub-cycle-native-input-icon").length, 0);
  assert.equal(objects.shapes.filter((shape) => shape.source.detector === "asset-hub-cycle-native-output-gem").length, 0);
  assert.equal(objects.shapes.filter((shape) => shape.source.detector === "asset-hub-cycle-native-output-gem-facet").length, 0);
  assert.equal(objects.textBoxes.length, 2);
  assert.equal(objects.textBoxes[0].text, "PM Portal\nPlatform");
  assert.equal(objects.textBoxes.every((textBox) => textBox.source.nativeComponentGroupId === "native-graphic-underlay-hub-spoke-center"), true);
  assert.equal(objects.shapes.every((shape) => shape.source.nativeComponentGroupId), true);
  assert.deepEqual(
    [...new Set(objects.shapes.map((shape) => shape.source.nativeComponentGroupId))].sort(),
    [
      "native-graphic-underlay-hub-spoke-left-bottom",
      "native-graphic-underlay-hub-spoke-left-mid",
      "native-graphic-underlay-hub-spoke-left-top",
      "native-graphic-underlay-hub-spoke-right-bottom",
      "native-graphic-underlay-hub-spoke-right-mid",
      "native-graphic-underlay-hub-spoke-right-top"
    ]
  );
  assert.equal(page.images[0].source.assetHubCycleObjectified, true);
  assert.equal(page.images[0].source.assetHubCycleInputIconsObjectified, false);
  assert.equal(page.images[0].source.assetHubCycleOutputGemsObjectified, false);
  assert.equal(page.images[0].source.dropErasedResidualAfterNativeRebuild, undefined);
  assert.equal(page.images[0].source.assetHubCycleResidualBoxes.length, 7);
  assert.equal(page.images[0].source.assetHubCycleResidualBoxes.filter((item) => item.name.endsWith("-icon")).length, 6);
  assert.ok(page.images[0].source.assetHubCycleResidualBoxes[0].box.w < page.images[0].box.w * 0.2);
  assert.ok(page.images[0].source.assetHubCycleResidualBoxes[0].box.h < page.images[0].box.h * 0.3);
});

