test("AI Skills closed-loop cycle rebuilds the central diagram without approximating side illustrations", () => {
  const page = {
    textBoxes: [
      { text: "Alskills:", box: { x: 153, y: 37, w: 160, h: 24 } },
      { text: "从需求捕获到交互交付的闭环引擎", box: { x: 301, y: 34, w: 502, h: 31 } }
    ],
    images: [
      {
        id: "native-graphic-underlay",
        type: "fidelity-crop",
        box: { x: 43.11, y: 106.13, w: 867.79, h: 387.75 },
        source: {
          detector: "cycle-illustration-underlay-crop",
          reason: "circular-icon-illustration-preserved-as-local-crop",
          layer: { layerType: "illustration-zone" }
        }
      }
    ]
  };

  const objects = createAssetHubCycleIllustrationObjects(page, { widthPt: 960, heightPt: 540 });
  const detectorCounts = objects.shapes.reduce((counts, shape) => {
    counts[shape.source.detector] = (counts[shape.source.detector] || 0) + 1;
    return counts;
  }, {});

  assert.equal(page.images[0].source.aiSkillsClosedLoopCycleObjectified, true);
  assert.equal(page.images[0].source.dropErasedResidualAfterNativeRebuild, true);
  assert.equal(page.images[0].source.assetHubCycleResidualBoxes.length, 0);
  assert.equal(detectorCounts["ai-skills-cycle-native-ring"], 1);
  assert.ok(detectorCounts["ai-skills-cycle-native-route"] >= 7);
  assert.equal(detectorCounts["ai-skills-cycle-native-card"], 4);
  assert.equal(detectorCounts["ai-skills-cycle-native-input-fragment"] || 0, 0);
  assert.equal(detectorCounts["ai-skills-cycle-native-output-stack"] || 0, 0);
  assert.ok(detectorCounts["ai-skills-cycle-native-card-icon"] >= 10);
  assert.equal(objects.textBoxes.filter((item) => item.source.detector === "ai-skills-cycle-native-text").length, 10);

  const byId = new Map(objects.shapes.map((shape) => [shape.id, shape]));
  assert.deepEqual(byId.get("native-graphic-underlay-ai-skills-cycle-blue-ring").box, { x: 300.84, y: 130.95, w: 354.06, h: 347.04 });
  assert.deepEqual(byId.get("native-graphic-underlay-ai-skills-cycle-card-prd").box, { x: 394.56, y: 102.25, w: 170.09, h: 93.45 });
  assert.deepEqual(byId.get("native-graphic-underlay-ai-skills-cycle-card-prototype").box, { x: 397.17, y: 399.66, w: 164.01, h: 91.90 });
  const inputRoute = byId.get("native-graphic-underlay-ai-skills-cycle-input-to-cycle");
  const outputRoute = byId.get("native-graphic-underlay-ai-skills-cycle-cycle-to-output");
  assert.ok(inputRoute.box.x >= page.images[0].box.x && inputRoute.box.x + inputRoute.box.w <= 320);
  assert.ok(outputRoute.box.x >= 700 && outputRoute.box.x + outputRoute.box.w <= page.images[0].box.x + page.images[0].box.w);
  const reviewBody = objects.textBoxes.find((item) => item.id.endsWith("card-review-body"));
  assert.equal(reviewBody.font.sizePt, 10.4);
  assert.equal(reviewBody.text.split("\n").length, 4);
});

