test("product brain vision samples native tile fills from the source image", () => {
  const sourceImage = makeImage(960, 540, "#FFFFFF");
  fillRect(sourceImage, 30, 80, 900, 390, "#123456");
  const page = {
    textBoxes: [
      { text: "终极远景：构建企业级「数字化产品大脑」", box: { x: 181, y: 26, w: 576, h: 31 } },
      { text: "多域聚合：一站式查阅全公司产品版图与系统血缘关系。", box: { x: 35, y: 463, w: 220, h: 38 } }
    ],
    images: [
      {
        id: "native-graphic-underlay",
        type: "fidelity-crop",
        box: { x: 34.49, y: 87.38, w: 887.28, h: 379.13 },
        source: {
          detector: "screenshot-process-underlay-crop",
          layer: { layerType: "screenshot-zone" }
        }
      }
    ]
  };

  const fallbackObjects = createProductBrainVisionObjects(JSON.parse(JSON.stringify(page)), { widthPt: 960, heightPt: 540 }, {
    allowHeuristicProductBrainVision: true
  });
  const objects = createProductBrainVisionObjects(page, { widthPt: 960, heightPt: 540 }, {
    allowHeuristicProductBrainVision: true,
    sourceImage,
    sampleTileFills: true
  });

  const sampledTile = objects.shapes.find((shape) =>
    shape.source.detector === "product-brain-vision-native-tile" && shape.source.sampledFill === true
  );
  const fallbackTile = fallbackObjects.shapes.find((shape) =>
    shape.source.detector === "product-brain-vision-native-tile"
    && shape.source.row === sampledTile.source.row
    && shape.source.col === sampledTile.source.col
  );
  assert.match(sampledTile.style.fill, /^#[0-9A-F]{6}$/);
  assert.notEqual(sampledTile.style.fill, fallbackTile.style.fill);
});

test("createVisualAtomNativeShapes objectifies grid atoms only in table or confident line diagrams", () => {
  const visualAtoms = [
    {
      id: "grid-h",
      kind: "grid-line-candidate",
      shapeHint: "grid-line-horizontal",
      axis: "h",
      box: { x: 40, y: 80, w: 320, h: 3 },
      color: "#8a8f98",
      nativeCandidate: true,
      density: 0.8
    },
    {
      id: "grid-v",
      kind: "grid-line-candidate",
      shapeHint: "grid-line-vertical",
      axis: "v",
      box: { x: 40, y: 80, w: 3, h: 160 },
      color: "#8a8f98",
      nativeCandidate: true,
      density: 0.8
    }
  ];

  const diagramShapes = createVisualAtomNativeShapes([visualAtomImage("diagram-zone", visualAtoms)]);
  const matrixDiagramShapes = createVisualAtomNativeShapes([visualAtomImage("diagram-zone", visualAtoms, "matrix-or-grid", {
    confidence: 0.88,
    nativeReadiness: "delegate-to-table-grid-parser"
  })]);
  const confidentDiagramShapes = createVisualAtomNativeShapes([visualAtomImage("diagram-zone", visualAtoms, "generic-node-diagram", {
    confidence: 0.92,
    nativeReadiness: "native-rebuild"
  })]);
  const tableShapes = createVisualAtomNativeShapes([visualAtomImage("table-zone", visualAtoms)]);

  assert.equal(diagramShapes.length, 0);
  assert.equal(matrixDiagramShapes.length, 2);
  assert.equal(confidentDiagramShapes.length, 2);
  assert.equal(tableShapes.length, 2);
  assert.ok(matrixDiagramShapes.every((shape) => shape.source.detector === "visual-atom-native-connector"));
  assert.ok(tableShapes.every((shape) => shape.source.detector === "visual-atom-native-connector"));
  assert.ok(confidentDiagramShapes.every((shape) => shape.source.detector === "visual-atom-native-connector"));
});

