test("createVisualAtomNativeShapes defers process diagram atoms while preserving screenshot residuals", () => {
  const visualAtoms = [
    {
      id: "frame-v",
      kind: "grid-line-candidate",
      shapeHint: "grid-line-vertical",
      axis: "v",
      box: { x: 200, y: 80, w: 5, h: 220 },
      color: "#317b8f",
      nativeCandidate: true,
      density: 0.9
    },
    {
      id: "frame-h",
      kind: "grid-line-candidate",
      shapeHint: "grid-line-horizontal",
      axis: "h",
      box: { x: 80, y: 300, w: 360, h: 5 },
      color: "#308276",
      nativeCandidate: true,
      density: 0.9
    },
    {
      id: "ui-shot",
      kind: "screenshot-crop",
      box: { x: 220, y: 110, w: 120, h: 90 },
      residualCandidate: true
    }
  ];
  const image = visualAtomImage("diagram-zone", visualAtoms, "process-with-screenshots", {
    confidence: 0.95,
    nativeReadiness: "hybrid-native-plus-residual-crops"
  });
  image.source.detector = "saturated-diagram-graphic-underlay-crop";
  image.source.layer.recommendedAction = "split-native-with-residual-crop";

  const sourceImage = { width: 960, height: 540, data: Buffer.alloc(960 * 540 * 4, 255) };
  for (let y = 20; y < 120; y += 1) {
    for (let x = 20; x < 160; x += 1) {
      const offset = (y * sourceImage.width + x) * 4;
      sourceImage.data[offset] = 20;
      sourceImage.data[offset + 1] = 96;
      sourceImage.data[offset + 2] = 170;
      sourceImage.data[offset + 3] = 255;
    }
  }
  const shapes = createVisualAtomNativeShapes([image], sourceImage, { widthPt: 960, heightPt: 540 });

  assert.equal(shapes.length, 0);
  assert.equal(image.source.objectifiedVisualAtoms, 0);
  assert.equal(image.source.deferredVisualAtomsDueToResidualOverlay, 2);
  assert.equal(image.source.visualAtomOverlayOnly, true);
  assert.equal(image.source.visualAtomFullyObjectified, false);
  assert.equal(image.source.dropErasedResidualAfterNativeRebuild, false);
});

