test("createStructuredIllustrationCardShellShapes emits native card borders for split illustration cards", () => {
  const visualAtoms = [
    {
      id: "separator-a",
      kind: "grid-line-candidate",
      axis: "v",
      box: { x: 320, y: 75, w: 7, h: 400 },
      nativeCandidate: true,
      residualCandidate: false
    },
    {
      id: "separator-b",
      kind: "grid-line-candidate",
      axis: "v",
      box: { x: 620, y: 75, w: 7, h: 400 },
      nativeCandidate: true,
      residualCandidate: false
    }
  ];
  const image = {
    id: "structured-illustration",
    box: { x: 68, y: 75, w: 840, h: 400 },
    source: {
      editable: false,
      detector: "illustration-card-graphic-underlay-crop",
      layer: {
        layerType: "illustration-zone",
        recommendedAction: "split-native-with-residual-crop",
        diagramUnderstanding: {
          archetype: "process-with-screenshots",
          confidence: 0.95,
          visualAtoms
        }
      }
    }
  };

  const shapes = createStructuredIllustrationCardShellShapes([image]);

  assert.equal(shapes.length, 6);
  assert.equal(image.source.structuredIllustrationShellObjectified, true);
  assert.equal(image.source.objectifiedStructuredIllustrationShells, 3);
  const backgrounds = shapes.filter((shape) => shape.source.detector === "structured-illustration-card-native-background");
  assert.equal(backgrounds.length, 3);
  assert.equal(shapes.filter((shape) => shape.source.detector === "structured-illustration-card-native-accent").length, 3);
  assert.equal(shapes.filter((shape) => shape.source.detector === "structured-illustration-card-native-border").length, 0);
  assert.deepEqual(backgrounds.map((shape) => shape.type), ["roundRect", "roundRect", "roundRect"]);
  assert.ok(backgrounds.every((shape) => shape.style.shadow));
  assert.ok(backgrounds[0].box.x < image.box.x);
  assert.ok(backgrounds[0].box.y < image.box.y);
  assert.ok(backgrounds[1].box.x - (backgrounds[0].box.x + backgrounds[0].box.w) >= 10);
  assert.ok(shapes.every((shape) => shape.source.layerSourceId === "structured-illustration"));
});

