test("createStructuredIllustrationCardTitleWarningShapes emits stable native warnings from card titles", () => {
  const cardShellShapes = [
    { box: { x: 68, y: 75, w: 262, h: 400 }, source: { detector: "structured-illustration-card-native-background" } },
    { box: { x: 330, y: 75, w: 299, h: 400 }, source: { detector: "structured-illustration-card-native-background" } },
    { box: { x: 629, y: 75, w: 277, h: 400 }, source: { detector: "structured-illustration-card-native-background" } }
  ];
  const textBoxes = [
    { text: "混沌的输入端", box: { x: 111, y: 74, w: 140, h: 24 } },
    { text: "瓶颈的处理端", box: { x: 410, y: 74, w: 140, h: 24 } },
    { text: "割裂的输出端", box: { x: 706, y: 74, w: 140, h: 24 } }
  ];

  const shapes = createStructuredIllustrationCardTitleWarningShapes(textBoxes, cardShellShapes);

  assert.equal(shapes.length, 9);
  assert.equal(shapes.filter((shape) => shape.type === "triangle").length, 3);
  assert.ok(shapes.every((shape) => shape.source.detector === "structured-illustration-warning-icon-native"));
  assert.ok(shapes.every((shape) => shape.source.warningVariant === "card-title-warning"));
  const triangles = shapes.filter((shape) => shape.source.iconPart === "triangle");
  assert.ok(triangles.every((shape, index) => shape.box.x > cardShellShapes[index].box.x + cardShellShapes[index].box.w * 0.05));
  assert.ok(triangles.every((shape, index) => shape.box.x < cardShellShapes[index].box.x + cardShellShapes[index].box.w * 0.08));
  assert.ok(triangles.every((shape, index) => shape.box.y > cardShellShapes[index].box.y + cardShellShapes[index].box.h * 0.045));
  assert.ok(triangles.every((shape, index) => shape.box.y < cardShellShapes[index].box.y + cardShellShapes[index].box.h * 0.065));
});

