test("detectSimpleStatusIcons skips colored components that overlap OCR text boxes", () => {
  const image = makeImage(160, 100, "#FFFFFF");
  fillRect(image, 60, 30, 44, 44, "#239F54");

  const withoutTextOverlap = detectSimpleStatusIcons(image, { widthPt: 160, heightPt: 100 }, []);
  assert.equal(withoutTextOverlap.shapes.length, 1);
  assert.equal(withoutTextOverlap.textBoxes[0].text, "✓");

  const withTextOverlap = detectSimpleStatusIcons(image, { widthPt: 160, heightPt: 100 }, [
    { box: { x: 55, y: 25, w: 55, h: 55 } }
  ]);
  assert.equal(withTextOverlap.shapes.length, 0);
  assert.equal(withTextOverlap.textBoxes.length, 0);
});

test("aggregate foreground fallback preserves dispersed thin graphics when no component survives", () => {
  const image = makeImage(240, 140, "#FFFFFF");
  for (let x = 24; x < 216; x += 12) {
    fillRect(image, x, 62, 4, 4, "#2F80ED");
    fillRect(image, x, 76, 4, 4, "#27AE60");
  }
  fillRect(image, 100, 40, 40, 40, "#2F80ED");

  const aggregate = aggregateForegroundComponent(image, []);
  assert.ok(aggregate.box.w > 120);
  assert.ok(aggregate.box.h > 40);
  assert.equal(shouldAddAggregateComponent(aggregate, [], image), true);
  assert.equal(shouldAddAggregateComponent(aggregate, [{ box: aggregate.box }], image), false);
});

