test("classifyResidualSplitComponent tags small non-rectangular saturated icons", () => {
  const icon = makeImage(80, 72, "#FFFFFF");
  for (let y = 0; y < icon.height; y += 1) {
    for (let x = 0; x < icon.width; x += 1) {
      const cx = Math.abs(x - 40) / 38;
      const cy = Math.abs(y - 36) / 34;
      if (cx + cy <= 1) setPixel(icon, x, y, "#F28A1A");
    }
  }
  const solidCard = makeImage(80, 72, "#FFFFFF");
  fillRect(solidCard, 4, 4, 72, 64, "#1C74BC");
  const neutralStatus = makeImage(80, 72, "#FFFFFF");
  for (let y = 0; y < neutralStatus.height; y += 1) {
    for (let x = 0; x < neutralStatus.width; x += 1) {
      const dx = x - 40;
      const dy = y - 36;
      if (dx * dx + dy * dy <= 31 * 31) setPixel(neutralStatus, x, y, "#8B8B8B");
      if (Math.abs(dx - dy) <= 3 || Math.abs(dx + dy) <= 3) setPixel(neutralStatus, x, y, "#FFFFFF");
    }
  }

  assert.deepEqual(classifyResidualSplitComponent(icon, { box: { w: 80, h: 72 } }, "split-erased-residual-crop"), {
    detector: "icon-residual-crop",
    nonEditableReason: "small icon preserved as local fidelity crop after native primitive erasure"
  });
  assert.deepEqual(classifyResidualSplitComponent(neutralStatus, { box: { w: 80, h: 72 } }, "split-erased-residual-crop"), {
    detector: "icon-residual-crop",
    nonEditableReason: "small icon preserved as local fidelity crop after native primitive erasure"
  });
  assert.equal(classifyResidualSplitComponent(solidCard, { box: { w: 80, h: 72 } }, "split-erased-residual-crop"), null);
  assert.equal(classifyResidualSplitComponent(icon, { box: { w: 80, h: 72 } }, "split-wide-residual-crop"), null);
});

