test("rebuildDeckFromWorkDir filters selected pages without renumbering source page indexes", () => {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "slideclone-page-filter-work-"));
  const workDir = path.join(tempDir, "page-filter.work");
  fs.mkdirSync(path.join(workDir, "ir"), { recursive: true });
  fs.writeFileSync(path.join(workDir, "ir", "deck.json"), JSON.stringify({
    slideSize: { widthPt: 960, heightPt: 540 },
    pages: [
      { pageIndex: 0, textBoxes: [{ id: "p1", text: "page 1", box: { x: 10, y: 10, w: 100, h: 20 } }] },
      { pageIndex: 1, textBoxes: [{ id: "p2", text: "page 2", box: { x: 10, y: 10, w: 100, h: 20 } }] },
      { pageIndex: 2, textBoxes: [{ id: "p3", text: "page 3", box: { x: 10, y: 10, w: 100, h: 20 } }] }
    ]
  }));

  assert.deepEqual(Array.from(parsePageSelection("2-3")), [1, 2]);
  assert.equal(shouldIncludePage(parsePageSelection("2"), { pageIndex: 1 }, 1), true);
  assert.equal(shouldIncludePage(parsePageSelection("2"), { pageIndex: 0 }, 0), false);

  const deck = rebuildDeckFromWorkDir(workDir, { preserveGraphics: false, pages: "2-3" });
  assert.deepEqual(deck.pages.map((page) => page.pageIndex), [1, 2]);
  assert.deepEqual(deck.pages.map((page) => page.textBoxes[0].text), ["page 2", "page 3"]);
});

test("replaceComponentTemplateCropsWhenFullyNative replaces only high-confidence pure plugin component crops", () => {
  const childLayout = {
    provider: "pptx-group-child-layout-v1",
    children: [
      { kind: "shape", box: { x: 0.04, y: 0.35, w: 0.18, h: 0.30 } },
      { kind: "shape", box: { x: 0.30, y: 0.35, w: 0.18, h: 0.30 } },
      { kind: "shape", box: { x: 0.56, y: 0.35, w: 0.18, h: 0.30 } },
      { kind: "shape", box: { x: 0.78, y: 0.35, w: 0.18, h: 0.30 } }
    ]
  };
  const processLayerSource = (id, pictureCount, layerType = "diagram-zone", overrides = {}) => ({
    detector: overrides.detector,
    componentRenderStrategy: { mode: "plugin-component-template" },
    layer: {
      layerType,
      templateFamily: "process-chain",
      diagramUnderstanding: {
        archetype: "process-chain",
        confidence: 0.9,
        nodeCount: 4,
        connectorCount: 3
      }
    },
    componentLocalAssets: [{
      provider: "officeplus",
      name: `${id}.pptx`,
      path: `C:\\OfficePLUS\\${id}.pptx`,
      recommendedComponentGroups: [{
        id: `${id}-group`,
        score: overrides.score ?? 84,
        childCount: 4,
        shapeCount: 4,
        pictureCount,
        connectorCount: 3,
        childLayout,
        topColors: [{ value: "#185ABD", count: 4 }]
      }]
    }]
  });
  const images = [
    { id: "pure-component", box: { x: 100, y: 100, w: 420, h: 160 }, source: processLayerSource("pure", 0) },
    { id: "foreground-component", box: { x: 100, y: 180, w: 420, h: 160 }, source: processLayerSource("foreground", 0, "diagram-zone", { detector: "foreground-graphic-crop", score: 70.5 }) },
    { id: "sparse-component", box: { x: 100, y: 220, w: 420, h: 160 }, source: processLayerSource("sparse", 0, "diagram-zone", { detector: "sparse-diagram-graphic-underlay-crop", score: 76.5 }) },
    { id: "weak-sparse-component", box: { x: 100, y: 240, w: 420, h: 160 }, source: processLayerSource("weak-sparse", 0, "diagram-zone", { detector: "sparse-diagram-graphic-underlay-crop", score: 72 }) },
    { id: "picture-component", box: { x: 100, y: 300, w: 420, h: 160 }, source: processLayerSource("picture", 1) },
    { id: "screenshot-component", type: "fidelity-crop", box: { x: 100, y: 120, w: 420, h: 160 }, source: processLayerSource("screenshot", 0, "screenshot-zone") }
  ];
  const generated = createComponentTemplateNativeShapes(images, { widthPt: 960, heightPt: 540 });
  const result = replaceComponentTemplateCropsWhenFullyNative(images, generated);
  const pureShapes = result.shapes.filter((shape) => shape.source.layerSourceId === "pure-component");
  const foregroundShapes = result.shapes.filter((shape) => shape.source.layerSourceId === "foreground-component");
  const sparseShapes = result.shapes.filter((shape) => shape.source.layerSourceId === "sparse-component");
  const pictureShapes = result.shapes.filter((shape) => shape.source.layerSourceId === "picture-component");
  const screenshotShapes = result.shapes.filter((shape) => shape.source.layerSourceId === "screenshot-component");

  assert.equal(result.images.some((image) => image.id === "pure-component"), false);
  assert.equal(result.images.some((image) => image.id === "foreground-component"), false);
  assert.equal(result.images.some((image) => image.id === "sparse-component"), false);
  assert.equal(result.images.some((image) => image.id === "weak-sparse-component"), true);
  assert.equal(result.images.some((image) => image.id === "picture-component"), true);
  assert.equal(result.images.some((image) => image.id === "screenshot-component"), true);
  assert.ok(pureShapes.length >= 7);
  assert.ok(pureShapes.every((shape) => shape.source.componentTemplateCropReplacedByNative === true));
  assert.ok(foregroundShapes.length >= 7);
  assert.ok(foregroundShapes.every((shape) => shape.source.componentTemplateCropReplacementReason === "complete-structured-plugin-component-rebuilt-natively"));
  assert.ok(sparseShapes.length >= 7);
  assert.ok(sparseShapes.every((shape) => shape.source.componentTemplateCropReplacementReason === "complete-structured-plugin-component-rebuilt-natively"));
  assert.deepEqual(
    [...new Set(pureShapes.map((shape) => shape.source.nativeComponentGroupId))],
    ["component-template-pure-component-pure-group"]
  );
  assert.ok(pureShapes.every((shape) => shape.source.nativeComponentPart));
  assert.ok(pureShapes.every((shape) => shape.source.nativeComponentAtomId.startsWith("component-template-pure-component-pure-group-")));
  assert.ok(pictureShapes.some((shape) => shape.source.componentTemplateGroupApplied === true));
  assert.deepEqual(
    [...new Set(pictureShapes.map((shape) => shape.source.nativeComponentGroupId))],
    ["component-template-picture-component-picture-group"]
  );
  assert.ok(screenshotShapes
    .filter((shape) => shape.source.componentTemplatePart === "process-node")
    .every((shape) => shape.style.fill === "none"));
  assert.equal(result.images.find((image) => image.id === "picture-component").source.componentTemplateCropReplacedByNative, false);
  assert.equal(
    result.images.find((image) => image.id === "picture-component").source.componentTemplateCropReplacementReason,
    "component-template-contains-picture-children"
  );
  assert.equal(
    result.images.find((image) => image.id === "screenshot-component").source.componentTemplateCropReplacementReason,
    "component-template-source-layer-requires-fidelity-crop"
  );
});

