test("replaceComponentTemplateCropsWhenFullyNative splits picture children into local residual crops", () => {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "slideclone-component-template-picture-"));
  const assetDir = path.join(tempDir, "assets");
  const sourceImage = makeImage(960, 540, "#FFFFFF");
  fillRect(sourceImage, 340, 130, 90, 80, "#1D4ED8");
  const childLayout = {
    provider: "pptx-group-child-layout-v1",
    children: [
      { kind: "shape", box: { x: 0.04, y: 0.34, w: 0.18, h: 0.30 } },
      { kind: "shape", box: { x: 0.30, y: 0.34, w: 0.18, h: 0.30 } },
      { kind: "picture", box: { x: 0.55, y: 0.18, w: 0.22, h: 0.55 } },
      { kind: "shape", box: { x: 0.80, y: 0.34, w: 0.16, h: 0.30 } }
    ]
  };
  const image = {
    id: "picture-split-component",
    box: { x: 100, y: 100, w: 420, h: 160 },
    source: {
      componentRenderStrategy: { mode: "plugin-component-template" },
      layer: {
        layerType: "diagram-zone",
        templateFamily: "process-chain",
        diagramUnderstanding: {
          archetype: "process-chain",
          confidence: 0.9,
          nodeCount: 3,
          connectorCount: 2
        }
      },
      componentLocalAssets: [{
        provider: "officeplus",
        name: "picture-split.pptx",
        path: "C:\\OfficePLUS\\picture-split.pptx",
        recommendedComponentGroups: [{
          id: "picture-split-group",
          score: 86,
          childCount: 4,
          shapeCount: 3,
          pictureCount: 1,
          connectorCount: 2,
          childLayout,
          topColors: [{ value: "#185ABD", count: 4 }]
        }]
      }]
    }
  };
  const generated = createComponentTemplateNativeShapes([image], { widthPt: 960, heightPt: 540 });
  const result = replaceComponentTemplateCropsWhenFullyNative([image], generated, {
    sourceImage,
    slideSize: { widthPt: 960, heightPt: 540 },
    assetDir,
    irDir: tempDir,
    deckName: "component-template",
    pageIndex: 0
  });
  const residual = result.images.find((item) => item.source.detector === "component-template-picture-residual-crop");
  const shapes = result.shapes.filter((shape) => shape.source.layerSourceId === "picture-split-component");

  assert.equal(result.images.some((item) => item.id === "picture-split-component"), false);
  assert.ok(residual);
  assert.ok(fs.existsSync(path.join(tempDir, residual.assetPath)));
  assert.ok(residual.box.w < image.box.w * 0.35);
  assert.equal(residual.source.componentTemplateCropSplitIntoResiduals, true);
  assert.equal(shapes.filter((shape) => shape.source.componentTemplatePart === "process-node").length, 3);
  assert.deepEqual(
    [...new Set(shapes.map((shape) => shape.source.nativeComponentGroupId))],
    ["component-template-picture-split-component-picture-split-group"]
  );
  assert.ok(shapes.every((shape) => shape.source.componentTemplateCropReplacedByNative === true));
  assert.ok(shapes.every((shape) => shape.source.componentTemplateCropSplitIntoResiduals === true));
});

