test("visibleTextBoxes clears hidden OCR overlay style for retained native text", () => {
  const result = visibleTextBoxes([
    {
      id: "ocr-title",
      text: "保留为可编辑标题",
      box: { x: 10, y: 10, w: 220, h: 28 },
      font: { sizePt: 20, color: "#111111", opacity: 0 },
      style: { visibility: "hidden", opacity: 0, marginLeftPt: 4 },
      source: { overlayVisibility: "hidden" }
    }
  ], null, { widthPt: 960, heightPt: 540 });

  assert.equal(result.length, 1);
  assert.equal(result[0].font.opacity, 1);
  assert.equal(result[0].style.visibility, "visible");
  assert.equal(result[0].style.opacity, 1);
  assert.equal(result[0].style.marginLeftPt, 0);
  assert.equal(result[0].source.overlayVisibility, "visible");
});

