test("comparison matrix crop preserves dense table-like diagrams as a single crop", () => {
  const slideSize = { widthPt: 960, heightPt: 540 };
  const texts = [
    ["传统工作方式", 205, 76, 170, 28],
    ["普通 AI 工具", 418, 76, 170, 28],
    ["PM Portal AI Skills", 645, 76, 240, 28],
    ["场景理解", 78, 153, 90, 24],
    ["人工翻阅大量历史材料", 192, 153, 190, 22],
    ["缺少公司上下文与域仓目录", 397, 153, 230, 22],
    ["深度结合真实系统架构与沉淀资产", 650, 153, 260, 22],
    ["流程引擎", 78, 250, 90, 24],
    ["手动推进各断裂环节", 192, 250, 190, 22],
    ["碎片化、一次性的临时问答", 397, 250, 230, 22],
    ["需求→PRD→评审→原型无缝串联", 650, 250, 260, 22],
    ["质量控制", 78, 346, 90, 24],
    ["依赖评审会人工纠错", 192, 346, 190, 22],
    ["仅生成文字，缺乏严谨逻辑校验", 397, 346, 230, 22],
    ["前置拦截风险，强制扫描完整性", 650, 346, 260, 22],
    ["资产沉淀", 78, 443, 90, 24],
    ["结果散落个人电脑各处", 192, 443, 190, 22],
    ["会话结束数据即刻丢失", 397, 443, 230, 22],
    ["产出自动落盘为标准分布式域仓资产", 650, 443, 260, 22]
  ];
  const textBoxes = texts.map(([text, x, y, w, h]) => ({ text, box: { x, y, w, h } }));
  const matrixBox = comparisonMatrixBounds(textBoxes, slideSize);
  assert.equal(shouldUseComparisonMatrixCrop({ matrixBox, textBoxes, slideSize }), true);
  assert.ok(matrixBox.w > 780);
  assert.ok(matrixBox.h > 360);
  const segments = segmentComparisonMatrix(matrixBox, slideSize);
  assert.equal(segments.length, 2);
  assert.ok(segments.every((box) => (box.w * box.h) / (slideSize.widthPt * slideSize.heightPt) < 0.65));
});

