  const irDir = path.join(tempDir, "ir");
  const assetDir = path.join(irDir, "assets");
  fs.mkdirSync(assetDir, { recursive: true });
  const sourceImage = makeImage(960, 540, "#FFFFFF");
  const assetFile = path.join(assetDir, "wms-underlay.png");
  writePng(assetFile, sourceImage);
  const image = {
    id: "wms-chain-minimum-unit",
    assetPath: "assets/wms-underlay.png",
    box: { x: 19, y: 108, w: 912, h: 227 },
    source: {
      detector: "wms-chain-underlay-crop",
      layer: {
        diagramUnderstanding: {
          archetype: "flow-card-chain",
          confidence: 0.92,
          nativeReadiness: "native-rebuild",
          nodeCount: 9,
          connectorCount: 8
        }
      }
    }
  };
  const textBoxes = [
    { text: "Tollgate1", box: { x: 280, y: 276, w: 80, h: 18 } },
    { text: "Tollgate2", box: { x: 510, y: 276, w: 80, h: 18 } },
    { text: "Tollgate3", box: { x: 740, y: 276, w: 80, h: 18 } }
  ];

  const crops = createWmsRouteMinimumUnitCrops({ image, textBoxes, sourceImage, slideSize: { widthPt: 960, heightPt: 540 }, irDir });
  image.source.wmsRouteChainMinimumUnitCrops = crops;
  const page = { images: [image], shapes: [], textBoxes: [] };
