  assert.equal(crops.length, 4);
  assert.equal(page.images.length, 4);
  assert.equal(page.images.filter((item) => item.source.detector === "wms-route-chain-document-icon-residual-crop").length, 1);
  assert.equal(page.images.filter((item) => item.source.detector === "wms-route-chain-icon-residual-crop").length, 3);
