test("minimum visual asset promotion replaces stale structural policies atomically", () => {
  const image = {
    id: "dense-radial-pictorial-unit",
    source: {
      detector: "foreground-aggregate-crop",
      editable: false,
      graphicExpressionPolicy: {
        kind: "structured-native",
        minimumUnitPolicy: "rebuild-semantic-structure",
        reasons: ["stale-structural-policy"]
      },
      componentRenderStrategy: {
        mode: "component-template",
        expressionPolicy: {
          kind: "structured-native",
          protectCrop: false
        }
      },
      layer: {
        layerType: "diagram-zone",
        componentRenderStrategy: {
          mode: "component-template"
        }
      }
    }
  };
  const promoted = promoteMinimumVisualAssetCropMetadata(image, {
    form: "screenshot-or-document",
    subtype: "screenshot-or-document-region",
    layerType: "screenshot-zone",
    recommendedAction: "keep-local-crop-and-overlay-external-text-only",
    reason: "search-widget screenshot is part of an indivisible pictorial unit",
    policy: {
      kind: "native-intended-gap",
      minimumUnitPolicy: "rebuild-semantic-structure-after-rule-or-template",
      protectCrop: false,
      reasons: ["stale-classification"]
    }
  });

  assert.equal(promoted.source.graphicExpressionPolicy.kind, "fidelity-crop");
  assert.equal(promoted.source.graphicExpressionPolicy.minimumUnitPolicy, "preserve-as-single-crop");
  assert.deepEqual(promoted.source.graphicExpressionPolicy.reasons, ["authoritative-screenshot-minimum-unit"]);
  assert.equal(promoted.source.componentRenderStrategy.mode, "preserve-local-crop");
  assert.equal(promoted.source.componentRenderStrategy.expressionPolicy.kind, "fidelity-crop");
  assert.equal(promoted.source.componentRenderStrategy.expressionPolicy.protectCrop, true);
  assert.equal(promoted.source.layer.componentRenderStrategy.expressionPolicy.kind, "fidelity-crop");
});

