test("entropy challenge page preserves fidelity crops while adding native helper shapes", () => {
  const slideSize = { widthPt: 960, heightPt: 540 };
  const image = makeImage(1280, 720, "#FFFFFF");
  const textBoxes = [
    { text: "产品资产的“摘增”挑战", box: { x: 58, y: 45, w: 320, h: 27 } },
    { text: "分散的飞书材料", box: { x: 138, y: 154, w: 136, h: 21 } },
    { text: "过期的历史PRD", box: { x: 198, y: 216, w: 142, h: 20 } },
    { text: "脱节的原型设计", box: { x: 73, y: 265, w: 137, h: 20 } },
    { text: "滞后的评审记录", box: { x: 183, y: 326, w: 137, h: 21 } },
    { text: "资产碎片化", box: { x: 72, y: 433, w: 113, h: 26 } },
    { text: "技能孤岛", box: { x: 262, y: 434, w: 91, h: 24 } },
    { text: "协作断层", box: { x: 71, y: 471, w: 93, h: 24 } }
  ];
  assert.equal(shouldUseEntropyChallengeCrops(textBoxes, slideSize), true);
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "entropy-crops-"));
  const crops = createEntropyChallengeCrops(image, textBoxes, slideSize, {
    assetDir: tmp,
    irDir: tmp,
    deckName: "deck",
    pageIndex: 1
  });
  assert.equal(crops.length, 2);
  assert.deepEqual(
    crops.map((item) => item.source.detector),
    ["entropy-challenge-crop", "entropy-challenge-island-crop"]
  );
  assert.ok(crops.every((item) => item.source.editable === false));
  assert.ok(crops.every((item) => item.source.skipVisualAtomRebuild === true));
  assert.ok(crops.every((item) => item.source.standaloneVisualAsset === true));
  assert.ok(crops.every((item) => item.source.intentionalMinimumUnitCrop === true));
  assert.ok(crops.every((item) => item.source.protectedMinimumUnit === true));
  assert.deepEqual(crops.map((item) => item.source.expressionForm), ["icon-or-illustration", "icon-or-illustration"]);
  assert.equal(crops[1].source.expressionSubtype, "perspective-island-illustration");
  assert.equal(crops[0].source.annotationTextErasedFromCrop, true);
  assert.equal(crops[0].source.componentRenderStrategy.mode, "preserve-crop-with-native-overlays");
  const annotations = createEntropyChallengeAnnotationObjects(textBoxes, crops, slideSize);
  assert.equal(annotations.shapes.length, 4);
  assert.equal(annotations.textBoxes.length, 4);
  assert.equal(annotations.textBoxes.every((item) => item.source.textErasedFromCrop === true), true);
  assert.deepEqual(
    [...new Set([...annotations.shapes, ...annotations.textBoxes].map((item) => item.source.nativeComponentGroupId))],
    [
      "entropy-challenge-annotation-0",
      "entropy-challenge-annotation-1",
      "entropy-challenge-annotation-2",
      "entropy-challenge-annotation-3"
    ]
  );
  const nativeFragments = createEntropyChallengeFragmentShapes(textBoxes, slideSize);
  assert.ok(nativeFragments.length >= 27);
  assert.ok(nativeFragments.every((shape) => shape.source.nativeRebuild === true));
  assert.ok(nativeFragments.every((shape) => /entropy-fragment-cloud-native/.test(shape.source.detector)));
  assert.equal(nativeFragments.filter((shape) => shape.source.detector === "entropy-fragment-cloud-native-text-stroke").length, 0);
  assert.equal(nativeFragments.filter((shape) => shape.source.detector === "entropy-fragment-cloud-native-dust").length, 6);
  const nativeIsland = createEntropyChallengeIslandShapes(textBoxes, slideSize);
  assert.ok(nativeIsland.length >= 38);
  assert.ok(nativeIsland.some((shape) => shape.source.detector === "entropy-island-native-frame"));
  assert.ok(nativeIsland.some((shape) => shape.source.detector === "entropy-island-native-grid"));
  assert.equal(nativeIsland.filter((shape) => shape.source.detector === "entropy-island-native-fine-grid").length, 6);
  assert.equal(nativeIsland.filter((shape) => shape.source.detector === "entropy-island-native-micro-mark").length, 8);
  assert.ok(nativeIsland.some((shape) => shape.source.detector === "entropy-island-native-route"));
  assert.ok(nativeIsland.some((shape) => shape.style?.dash === "dash"));
  assert.equal(shouldUseEntropyChallengeCrops(textBoxes.slice(0, 5), slideSize), false);
});

test("entropy challenge crops stay protected by default and can be opt-in replaced after high native coverage", () => {
  const slideSize = { widthPt: 960, heightPt: 540 };
  const textBoxes = [
    { text: "产品资产的“熵增”挑战", box: { x: 58, y: 45, w: 320, h: 27 } },
    { text: "分散的飞书材料", box: { x: 138, y: 154, w: 136, h: 21 } },
    { text: "过期的历史PRD", box: { x: 198, y: 216, w: 142, h: 20 } },
    { text: "脱节的原型设计", box: { x: 73, y: 265, w: 137, h: 20 } },
    { text: "滞后的评审记录", box: { x: 183, y: 326, w: 137, h: 21 } },
    { text: "资产碎片化", box: { x: 72, y: 433, w: 113, h: 26 } },
    { text: "技能孤岛", box: { x: 262, y: 434, w: 91, h: 24 } },
    { text: "协作断层", box: { x: 71, y: 471, w: 93, h: 24 } }
  ];
  const images = [
    { id: "fragment", box: { x: 40, y: 118, w: 330, h: 294 }, source: { detector: "entropy-challenge-crop" } },
    { id: "island", box: { x: 350, y: 96, w: 580, h: 356 }, source: { detector: "entropy-challenge-island-crop" } }
  ];
  const weakPage = { images: images.map((image) => ({ ...image, source: { ...image.source } })), textBoxes };
  assert.equal(dropEntropyChallengeCropsWhenNativeCoverage(weakPage, []), false);
  assert.equal(weakPage.images.length, 2);

  const strongPage = { images: images.map((image) => ({ ...image, source: { ...image.source } })), textBoxes };
  const shapes = [
    ...createEntropyChallengeFragmentShapes(textBoxes, slideSize),
    ...createEntropyChallengeIslandShapes(textBoxes, slideSize)
  ];
  assert.equal(dropEntropyChallengeCropsWhenNativeCoverage(strongPage, shapes), false);
  assert.equal(strongPage.images.length, 2);

  assert.equal(dropEntropyChallengeCropsWhenNativeCoverage(strongPage, shapes, {
    allowNativeApproximation: true
  }), true);
  assert.equal(strongPage.images.length, 0);

  const finalTextOnlyPage = {
    images: images.map((image) => ({ ...image, source: { ...image.source } })),
    textBoxes: textBoxes.filter((item) => /产品资产|资产碎片化|技能孤岛|协作断层|维护高/.test(item.text))
  };
  assert.equal(dropEntropyChallengeCropsWhenNativeCoverage(finalTextOnlyPage, shapes, {
    allowNativeApproximation: true
  }), true);
  assert.equal(finalTextOnlyPage.images.length, 0);
});

