test("entropy challenge micro details are driven by source image evidence", () => {
  const slideSize = { widthPt: 960, heightPt: 540 };
  const textBoxes = [
    { text: "产品资产的“熵增”挑战", box: { x: 58, y: 45, w: 320, h: 27 } },
    { text: "分散的飞书材料", box: { x: 138, y: 154, w: 136, h: 21 } },
    { text: "过期的历史PRD", box: { x: 198, y: 216, w: 142, h: 20 } },
    { text: "脱节的原型设计", box: { x: 73, y: 265, w: 137, h: 20 } },
    { text: "滞后的评审记录", box: { x: 183, y: 326, w: 137, h: 21 } },
    { text: "资产碎片化", box: { x: 72, y: 433, w: 113, h: 26 } },
    { text: "技能孤岛", box: { x: 262, y: 434, w: 91, h: 24 } },
    { text: "协作断层", box: { x: 71, y: 471, w: 93, h: 24 } }
  ];
  const blank = makeImage(960, 540, "#FFFFFF");

  assert.equal(
    createEntropyChallengeFragmentShapes(textBoxes, slideSize, blank)
      .filter((shape) => shape.source.detector === "entropy-fragment-cloud-native-dust").length,
    0
  );
  assert.equal(
    createEntropyChallengeIslandShapes(textBoxes, slideSize, blank)
      .filter((shape) => shape.source.detector === "entropy-island-native-micro-mark").length,
    0
  );

  const sourceImage = makeImage(960, 540, "#FFFFFF");
  fillRect(sourceImage, 58, 165, 4, 4, "#F07105");
  fillRect(sourceImage, 346, 185, 5, 5, "#F48A2A");
  fillRect(sourceImage, 150, 160, 5, 5, "#F07105");
  fillRect(sourceImage, 607, 138, 7, 3, "#2B638F");
  fillRect(sourceImage, 668, 176, 5, 5, "#D9782B");
  const fragments = createEntropyChallengeFragmentShapes(textBoxes, slideSize, sourceImage);
  const island = createEntropyChallengeIslandShapes(textBoxes, slideSize, sourceImage);
  const dust = fragments.filter((shape) => shape.source.detector === "entropy-fragment-cloud-native-dust");
  const microMarks = island.filter((shape) => shape.source.detector === "entropy-island-native-micro-mark");

  assert.equal(dust.length, 2);
  assert.ok(dust.every((shape) => shape.source.imageEvidence === true));
  assert.ok(dust.every((shape) => shape.style.fill.startsWith("#")));
  assert.ok(dust.every((shape) => shape.style.opacity < 1));
  assert.equal(microMarks.length, 2);
  assert.ok(microMarks.every((shape) => shape.source.imageEvidence === true));
  assert.ok(microMarks.every((shape) => shape.style.opacity < 1));
});

