test("workflow cover separates native title text from decorative and brand crops", () => {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "workflow-cover-text-free-bands-"));
  const slideSize = { widthPt: 960, heightPt: 540 };
  const image = makeImage(1280, 720, "#FFFFFF");
  fillRect(image, 0, 0, 1280, 405, "#18236B");
  // Simulate a title glyph that protrudes above the OCR evidence rectangle.
  // This is the failure mode that previously produced a source-text ghost
  // beneath the native editable title.
  fillRect(image, 400, 404, 40, 5, "#000000");
  const textBoxes = [
    { text: "AI Skills 核心能力矩阵", box: { x: 145, y: 329, w: 666, h: 51 }, font: {} },
    { text: "重塑产品交付工作流 —— 从经验依赖到数智赋能", box: { x: 133, y: 407, w: 691, h: 31 }, font: {} },
    { text: "H", box: { x: 358, y: 485, w: 12, h: 8 }, font: {}, style: {}, source: {} },
    { text: "数智向光·效率先锋 | 产品 AI 工作台", box: { x: 300, y: 499, w: 360, h: 24 }, font: {}, style: {}, source: {} }
  ];

  const backgrounds = createDecorativeCoverBackground(image, textBoxes, slideSize, {
    assetDir: tmp,
    irDir: tmp,
    deckName: "workflow",
    pageIndex: 0,
    mode: "cover"
  });
  normalizeDecorativeCoverTextBoxes(textBoxes, true);

  assert.equal(backgrounds.length, 2);
  assert.deepEqual(backgrounds[0].box, { x: 0, y: 0, w: 960, h: 309 });
  assert.equal(backgrounds[0].source.textFreeBandSplit, true);
  assert.equal(backgrounds[0].source.textErasedFromCrop, true);
  assert.equal(backgrounds[0].source.textMaskPaddingPt, 28);
  assert.equal(backgrounds[0].source.textMaskCount, 4);
  const topCrop = readPng(path.join(tmp, backgrounds[0].assetPath));
  const protrudingGlyphOffset = (406 * topCrop.width + 410) * 4;
  assert.notDeepEqual([...topCrop.rgba.subarray(protrudingGlyphOffset, protrudingGlyphOffset + 4)], [0, 0, 0, 255]);
  assert.equal(backgrounds[1].source.detector, "decorative-cover-brand-strip");
  assert.equal(backgrounds[1].source.intentionalBrandAsset, true);
  assert.equal(textBoxes[0].style?.visibility, undefined);
  assert.equal(textBoxes[0].font.sizePt, 54);
  assert.equal(textBoxes[0].source.textRole, "title");
  assert.equal(textBoxes[2].style.visibility, "hidden");
  assert.equal(textBoxes[3].source.overlayVisibility, "hidden");
});

