test("mixed diagram underlay erases text pixels and declares a hybrid diagram policy", () => {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "mixed-diagram-underlay-"));
  const image = makeImage(960, 540, "#FFFFFF");
  fillRect(image, 100, 160, 90, 24, "#111111");
  fillRect(image, 320, 220, 90, 70, "#2F80ED");
  const textBoxes = Array.from({ length: 24 }, (_, index) => ({
    text: `label-${index}`,
    box: {
      x: 52 + (index % 3) * 299,
      y: 130 + Math.floor(index / 3) * 48,
      w: 247,
      h: 30
    }
  }));
  const masks = [{ x: 92, y: 152, w: 106, h: 40 }];
  const crops = createMixedDiagramUnderlayCrop(
    image,
    textBoxes,
    { widthPt: 960, heightPt: 540 },
    { assetDir: tempDir, irDir: tempDir, deckName: "mixed", pageIndex: 0 },
    { box: { x: 30, y: 20, w: 900, h: 500 } },
    Array.from({ length: 5 }, () => ({ box: { x: 80, y: 200, w: 760, h: 1 } })),
    masks
  );

  assert.equal(crops.length, 1);
  assert.equal(crops[0].source.textErasedFromCrop, true);
  assert.equal(crops[0].source.semanticSplitOwnsLayer, true);
  assert.equal(crops[0].source.expressionForm, "complex-diagram");
  assert.equal(crops[0].source.expressionSubtype, "mixed-diagram-hybrid");
  assert.equal(crops[0].source.recommendedAction, "split-native-with-residual-crop");

  const refreshed = refreshImageExpressionMetadata(crops[0]);
  assert.equal(refreshed.source.expressionSubtype, "mixed-diagram-hybrid");
  assert.equal(refreshed.source.recommendedAction, "split-native-with-residual-crop");

  const crop = readPng(path.join(tempDir, crops[0].assetPath));
  const erasedOffset = (Math.round(160 - crops[0].box.y) * crop.width + Math.round(100 - crops[0].box.x)) * 4;
  const graphicOffset = (Math.round(220 - crops[0].box.y) * crop.width + Math.round(320 - crops[0].box.x)) * 4;
  assert.ok(crop.rgba[erasedOffset] >= 245 && crop.rgba[erasedOffset + 1] >= 245 && crop.rgba[erasedOffset + 2] >= 245);
  assert.deepEqual(Array.from(crop.rgba.slice(graphicOffset, graphicOffset + 3)), [47, 128, 237]);

  eraseObjectifiedLayerPrimitives({
    page: { images: crops },
    sourceImage: image,
    textBoxes: [{ text: "editable label", box: { x: 92, y: 152, w: 106, h: 40 } }],
    primitiveShapes: [{
      id: "native-card",
      type: "rect",
      box: { x: 320, y: 220, w: 90, h: 70 },
      source: {
        layerSourceId: crops[0].id,
        detector: "visual-atom-native-rect"
      }
    }],
    slideSize: { widthPt: 960, heightPt: 540 },
    irDir: tempDir
  });
  const postPrimitiveErase = readPng(path.join(tempDir, crops[0].assetPath));
  assert.ok(postPrimitiveErase.rgba[erasedOffset] >= 245);
  assert.ok(postPrimitiveErase.rgba[graphicOffset] >= 245);
});

