test("eraseMasks fills text holes with nearby local background color", () => {
  const image = makeImage(80, 50, "#FFFFFF");
  fillRect(image, 10, 10, 60, 30, "#2FA66A");
  fillRect(image, 28, 20, 20, 8, "#111111");
  const mask = { x: 26, y: 18, w: 24, h: 12 };

  const sampled = sampleMaskBackgroundColor(image, mask);
  assert.ok(sampled.g > sampled.r);
  assert.ok(sampled.g > sampled.b);

  const erased = eraseMasks(image, [mask]);
  const center = getPixel(erased, 34, 23);
  assert.ok(center.g > center.r);
  assert.ok(center.g > center.b);
});

test("sampleUniformPageBackgroundFill samples a consistent inset background and rejects mixed edges", () => {
  const inset = makeImage(100, 60, "#FFFFFF");
  fillRect(inset, 1, 1, 98, 58, "#F2F2F7");
  assert.equal(sampleUniformPageBackgroundFill(inset), "#F2F2F7");

  const mixed = makeImage(100, 60, "#FFFFFF");
  fillRect(mixed, 2, 2, 48, 56, "#DCEEFF");
  fillRect(mixed, 50, 2, 48, 56, "#FFE4D6");
  assert.equal(sampleUniformPageBackgroundFill(mixed), "#FFFFFF");
});

test("eraseMasks supports narrow line masks without erasing the full bounding rectangle", () => {
  const image = makeImage(80, 80, "#FFFFFF");
  drawLine(image, 10, 10, 70, 70, "#1F78C8");
  fillRect(image, 12, 66, 10, 10, "#F28A20");

  const erased = eraseMasks(image, [{ kind: "line", x1: 10, y1: 10, x2: 70, y2: 70, width: 7 }]);

  assert.ok(colorDistanceForTest(getPixel(erased, 40, 40), parseHex("#FFFFFF")) < 5);
  assert.ok(colorDistanceForTest(getPixel(erased, 16, 70), parseHex("#F28A20")) < 5);
});

test("sampleInkColor chooses high-contrast light text on colored backgrounds", () => {
  const image = makeImage(100, 60, "#2FA66A");
  fillRect(image, 40, 24, 20, 8, "#FFFFFF");
  assert.equal(sampleInkColor(image, { x: 20, y: 10, w: 60, h: 35 }, { widthPt: 100, heightPt: 60 }, "#111111"), "#FFFFFF");

  const blueBanner = makeImage(160, 50, "#2375C8");
  fillRect(blueBanner, 30, 20, 80, 8, "#FFFFFF");
  assert.equal(sampleInkColor(blueBanner, { x: 10, y: 8, w: 130, h: 28 }, { widthPt: 160, heightPt: 50 }, "#111111"), "#FFFFFF");

  const whitePage = makeImage(100, 60, "#FFFFFF");
  fillRect(whitePage, 40, 24, 20, 8, "#111111");
  const sampled = sampleInkColor(whitePage, { x: 20, y: 10, w: 60, h: 35 }, { widthPt: 100, heightPt: 60 }, "#111111");
  assert.match(sampled, /^#1[01]1[01]1[01]$/);

  const sampledWithBadFallback = sampleInkColor(whitePage, { x: 20, y: 10, w: 60, h: 35 }, { widthPt: 100, heightPt: 60 }, "#FFFFFF");
  assert.match(sampledWithBadFallback, /^#1[01]1[01]1[01]$/);

  const wideTextBox = makeImage(800, 80, "#FFFFFF");
  fillRect(wideTextBox, 40, 55, 360, 8, "#111111");
  const sampledWide = sampleInkColor(wideTextBox, { x: 0, y: 0, w: 800, h: 80 }, { widthPt: 800, heightPt: 80 }, "#FFFFFF");
  assert.match(sampledWide, /^#1[01]1[01]1[01]$/);
});

