test("wide bottom value banners with moderate gradients can become native gradient backgrounds", () => {
  const image = makeImage(500, 220, "#FFFFFF");
  for (let x = 0; x < 500; x += 1) {
    const ratio = x / 499;
    const r = Math.round(0x00 + ratio * (0xD0 - 0x00));
    const g = Math.round(0x40 + ratio * (0x80 - 0x40));
    const b = Math.round(0xD0 + ratio * (0x20 - 0xD0));
    fillRect(image, x, 170, 1, 44, `#${r.toString(16).padStart(2, "0")}${g.toString(16).padStart(2, "0")}${b.toString(16).padStart(2, "0")}`);
  }
  const banner = {
    id: "banner",
    box: { x: 0, y: 170, w: 500, h: 44 },
    source: {
      expressionForm: "value-banner",
      expressionSubtype: "value-banner-strip",
      detector: "bottom-banner-crop"
    }
  };

  const shapes = createValueBannerBackgroundShapes([banner], [], image, { widthPt: 500, heightPt: 220 });

  assert.equal(shapes.length, 1);
  assert.equal(shapes[0].source.detector, "value-banner-native-wide-gradient-background");
  assert.equal(shapes[0].style.gradient.type, "linear");
  assert.deepEqual(shapes[0].style.gradient.stops.map((stop) => stop.position), [0, 0.5, 1]);
  assert.equal(banner.source.valueBannerObjectified, true);
  assert.equal(banner.source.objectifiedValueBannerApproximateGradient, true);
});

