test("suppressRedundantTableGridScaffoldCoveredByVisualAtoms removes large scaffold grid over rich native diagram atoms", () => {
  const layerSourceId = "native-graphic-underlay";
  const gridLines = [
    { id: "grid-top", type: "line", box: { x: 36, y: 113, w: 894, h: 0 }, source: { detector: "table-zone-native-grid-line", layerSourceId } },
    { id: "grid-mid", type: "line", box: { x: 36, y: 145, w: 894, h: 0 }, source: { detector: "table-zone-native-grid-line", layerSourceId } },
    { id: "grid-bottom", type: "line", box: { x: 36, y: 423, w: 894, h: 0 }, source: { detector: "table-zone-native-grid-line", layerSourceId } },
    { id: "grid-left", type: "line", box: { x: 36, y: 113, w: 0, h: 310 }, source: { detector: "table-zone-native-grid-line", layerSourceId } },
    { id: "grid-right", type: "line", box: { x: 930, y: 113, w: 0, h: 310 }, source: { detector: "table-zone-native-grid-line", layerSourceId } }
  ];
  const nodes = Array.from({ length: 8 }, (_, index) => ({
    id: `node-${index}`,
    type: "roundRect",
    box: { x: 90 + index * 82, y: 180 + (index % 2) * 72, w: 58, h: 32 },
    source: { detector: index % 2 ? "visual-atom-native-ellipse" : "visual-atom-native-rect", layerSourceId }
  }));
  const connectors = Array.from({ length: 7 }, (_, index) => ({
    id: `connector-${index}`,
    type: "line",
    box: { x: 120 + index * 84, y: 210, w: 70, h: 24 },
    source: { detector: "visual-atom-native-connector", layerSourceId }
  }));
  const cellFill = {
    id: "cell-fill",
    type: "rect",
    box: { x: 80, y: 170, w: 120, h: 58 },
    source: { detector: "table-zone-native-cell-fill", layerSourceId }
  };

  const filtered = suppressRedundantTableGridScaffoldCoveredByVisualAtoms(
    [...gridLines, cellFill, ...nodes, ...connectors],
    { width: 960, height: 540 }
  );

  assert.equal(filtered.some((shape) => shape.source.detector === "table-zone-native-grid-line"), false);
  assert.equal(filtered.some((shape) => shape.id === "cell-fill"), true);
  assert.equal(filtered.filter((shape) => /^visual-atom-native-/.test(shape.source.detector)).length, 15);
});

