test("createNetworkDiagramShapes preserves product vision dense networks and extracts search chrome", (t) => {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "slideclone-dense-radial-hero-"));
  t.after(() => fs.rmSync(tempDir, { recursive: true, force: true }));
  const sourceImage = makeImage(960, 540, "#FFFFFF");
  const image = {
    id: "product-vision-network",
    assetPath: "product-vision-network.png",
    box: { x: 64, y: 88, w: 826, h: 378 },
    source: {
      detector: "foreground-aggregate-crop",
      pageText: "终局视野：企业级AI智能产品底座 复利引擎",
      preferDetailedDenseRadialNetworkComponent: true,
      componentRenderStrategy: {
        mode: "preserve-local-crop"
      },
      layer: {
        layerType: "diagram-zone",
        areaRatio: 0.6,
        recommendedAction: "attempt-native-reconstruction",
        diagramUnderstanding: {
          visualAtomKindCounts: {
            "grid-line-candidate": 12
          }
        }
      }
    }
  };
  drawSyntheticNetwork(sourceImage, image.box, 72);
  const searchX = Math.round(image.box.x + image.box.w * 0.75);
  const searchY = Math.round(image.box.y + image.box.h * 0.43);
  const searchW = Math.round(Math.min(220, Math.max(170, image.box.w * 0.24)));
  const searchH = Math.round(Math.min(56, Math.max(38, image.box.h * 0.13)));
  fillRect(sourceImage, searchX, searchY, searchW, searchH, "#D9DEE8");
  fillRect(sourceImage, searchX + 2, searchY + 2, searchW - 4, searchH - 4, "#FFFFFF");
  fillRect(sourceImage, searchX + 14, searchY + 13, 10, 10, "#6A717A");
  writePng(path.join(tempDir, image.assetPath), sourceImage);

  const shapes = createNetworkDiagramShapes(
    [image],
    sourceImage,
    { widthPt: 960, heightPt: 540 },
    { irDir: tempDir }
  );

  assert.equal(image.source.networkDiagramObjectified, undefined);
  assert.equal(image.source.denseRadialNetworkPreservedAsCrop, true);
  assert.equal(image.source.detector, "dense-radial-network-hero-crop");
  assert.equal(image.source.expressionForm, "icon-or-illustration");
  assert.equal(image.source.expressionSubtype, "dense-radial-network-hero");
  assert.equal(image.source.componentRenderStrategy.mode, "preserve-crop-with-native-overlays");
  assert.equal(image.source.skipVisualAtomRebuild, true);
  assert.equal(image.source.preserveResidualCropUnderNativeRebuild, true);
  assert.equal(image.source.denseRadialNetworkSummarized, undefined);
  assert.equal(image.source.denseRadialNetworkComponentObjectified, undefined);
  assert.equal(image.source.searchControlErasedFromCrop, true);
  assert.equal(shapes.length, 4);
  assert.deepEqual(
    [...new Set(shapes.map((shape) => shape.source.nativeComponentGroupId))],
    ["product-vision-network-network-search-control"]
  );
  const crop = readPng(path.join(tempDir, image.assetPath));
  assert.equal(crop.width, 826);
  assert.equal(crop.height, 378);
  assert.equal(image.source.dropErasedResidualAfterNativeRebuild, false);
});

