test("createFoundationCapabilityNetworkObjects rebuilds a foundation banner, capabilities, and domain warehouses", () => {
  const image = {
    id: "foundation-network",
    box: { x: 49, y: 103, w: 861, h: 391 },
    source: {
      detector: "foreground-graphic-underlay-crop",
      layer: {
        layerType: "table-zone",
        diagramUnderstanding: {
          evidence: {
            semanticText: "组织级产品底座 多域聚合 知识复用 AI增强 标准治理 业务域仓A 业务域仓B 业务域仓C"
          }
        }
      }
    }
  };

  const objects = createFoundationCapabilityNetworkObjects([image], [], { widthPt: 960, heightPt: 540 });

  assert.equal(image.source.foundationCapabilityNetworkObjectified, true);
  assert.equal(objects.shapes.filter((item) => item.source.detector === "foundation-network-native-capability").length, 4);
  assert.equal(objects.shapes.filter((item) => item.source.detector === "foundation-network-native-domain").length, 3);
  assert.equal(objects.shapes.filter((item) => item.source.detector === "foundation-network-native-endpoint").length, 2);
  const networkConnectors = objects.shapes.filter((item) => item.source.detector === "foundation-network-native-connector");
  assert.equal(networkConnectors.length, 3);
  assert.equal(networkConnectors.filter((item) => item.style.startArrow === "triangle").length, 1);
  assert.equal(networkConnectors.filter((item) => item.style.endArrow === "triangle").length, 2);
  assert.equal(networkConnectors.filter((item) => item.type === "freeform").length, 2);
  assert.equal(networkConnectors.filter((item) => item.type === "freeform").every((item) => item.style.freeformSegments.some((segment) => segment.type === "cubicBezTo")), true);
  assert.equal(objects.textBoxes.filter((item) => /description-/.test(item.id)).length, 4);
  const firstDescription = objects.textBoxes.find((item) => /description-0/.test(item.id));
  assert.equal(firstDescription.font.sizePt, 13.5);
  assert.equal(firstDescription.box.w, 168);
  assert.equal(firstDescription.runs.length, 2);
  assert.equal(firstDescription.runs[0].text, "无界聚合：");
  assert.equal(firstDescription.runs[0].font.weight, "bold");
  assert.equal(firstDescription.runs[0].font.sizePt, 13.5);
  assert.equal(firstDescription.runs[1].font.weight, "regular");
  assert.equal(objects.textBoxes.some((item) => item.text === "业务域仓 B"), true);
  assert.deepEqual(
    [...new Set([...objects.shapes, ...objects.textBoxes].map((item) => item.source.nativeComponentGroupId))].sort(),
    [
      "foundation-network-foundation-backbone",
      "foundation-network-foundation-capability-0",
      "foundation-network-foundation-capability-1",
      "foundation-network-foundation-capability-2",
      "foundation-network-foundation-capability-3",
      "foundation-network-foundation-domain-0",
      "foundation-network-foundation-domain-1",
      "foundation-network-foundation-domain-2",
      "foundation-network-foundation-shell"
    ]
  );
  assert.equal([...objects.shapes, ...objects.textBoxes].every((item) => item.source.nativeComponentMinimumUnit === "semantic-component"), true);
});

