test("triangle topology node purification removes foreign-color arrow fragments", () => {
  const crop = makeImage(120, 100, "#FFFFFF");
  fillRect(crop, 4, 0, 18, 100, "#2878D4");
  fillRect(crop, 34, 24, 68, 68, "#F58A1F");

  const result = purifyTriangleTopologyNodeCrop(crop, "left-node");

  assert.equal(result.purified, true);
  assert.ok(result.image.width < crop.width);
  let bluePixels = 0;
  for (let y = 0; y < result.image.height; y += 1) {
    for (let x = 0; x < result.image.width; x += 1) {
      const offset = (y * result.image.width + x) * 4;
      const r = result.image.rgba[offset];
      const g = result.image.rgba[offset + 1];
      const b = result.image.rgba[offset + 2];
      const a = result.image.rgba[offset + 3];
      if (b > r * 1.15 && b > g * 1.08 && a >= 64) bluePixels += 1;
    }
  }
  assert.equal(bluePixels, 0);
});

