test("fully objectified process-with-screenshots diagrams split residuals instead of preserving one large crop", () => {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "slideclone-process-full-native-"));
  const residual = makeImage(865, 357, "#FFFFFF");
  fillRect(residual, 60, 40, 300, 180, "#F28C20");
  fillRect(residual, 520, 70, 160, 60, "#24A867");
  fillRect(residual, 650, 165, 120, 54, "#BEEBD8");
  const assetPath = path.join(tempDir, "process-case.png");
  writePng(assetPath, residual);
  const image = {
    id: "process-case",
    type: "fidelity-crop",
    assetPath,
    box: { x: 44, y: 154, w: 865, h: 357 },
    source: {
      detector: "structured-case-graphic-underlay-crop",
      primitiveErased: true,
      reason: "case-study-diagram-graphics-preserved-as-content-region-crop",
      layer: {
        layerType: "diagram-zone",
        areaRatio: 0.50,
        recommendedAction: "split-native-with-residual-crop",
        diagramUnderstanding: {
          archetype: "process-with-screenshots"
        }
      }
    }
  };

  createProcessWithScreenshotsFlowObjects([image], null, { widthPt: 960, heightPt: 540 });
  const split = splitErasedResidualCrop(image, tempDir);

  assert.equal(image.source.processWithScreenshotsFullyObjectified, true);
  assert.equal(image.source.processWithScreenshotsSplit, true);
  assert.ok(split.length >= 4);
  assert.equal(split.some((item) => item.source.residualRegion === "right-flow"), false);
  assert.equal(split.some((item) => item.source.residualRegion === "left-illustration"), false);
  assert.ok(split.every((item) => item.box.w < image.box.w));
});

