test("PRD auto generation keeps the complex engine as a source-faithful minimum crop when assets are available", () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "slideclone-prd-engine-crop-"));
  try {
    const sourceImage = makeImage(960, 540, "#FFFFFF");
    const image = {
      id: "native-graphic-underlay",
      box: { x: 72.35, y: 115.13, w: 792.44, h: 385.5 },
      source: { detector: "screenshot-process-underlay-crop", reason: "document-generation-flow-illustration-preserved-as-local-crop" }
    };
    const textBoxes = [{ text: "PRD自动生成：告别重复性的标准化表达", box: { x: 169.81, y: 53.25, w: 617.01, h: 27 } }];
    const rawTextBoxes = [
      { text: "PRD生成", box: { x: 376.73, y: 256.88, w: 107.21, h: 24 }, font: { sizePt: 17.28 } },
      { text: "Skill", box: { x: 405.97, y: 285.75, w: 50.98, h: 22.88 }, font: { sizePt: 16.47 } }
    ];
    const generatedImages = [];
    const shapes = createPrdGenerationFlowShapes([image], textBoxes, sourceImage, { widthPt: 960, heightPt: 540 }, {
      rawTextBoxes,
      assetDir: root,
      irDir: root,
      deckName: "fixture",
      pageIndex: 6,
      generatedImages
    });

    assert.equal(generatedImages.length, 1);
    assert.equal(generatedImages[0].source.detector, "prd-auto-generation-engine-illustration-crop");
    assert.ok(fs.existsSync(path.join(root, generatedImages[0].assetPath)));
    assert.equal(shapes.some((shape) => shape.source?.detector === "prd-generation-flow-native-machine"), false);
    assert.equal(image.source.prdGenerationNativeTextBoxes.some((item) => /^(?:PRD生成|Skill)$/.test(item.text)), false);
  } finally {
    fs.rmSync(root, { recursive: true, force: true });
  }
});

