test("materializePrototypeValidationResidualCrops writes wand residual images before parent crop removal", () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "prototype-validation-residual-"));
  const assetFile = path.join(dir, "source.png");
  writePng(assetFile, makeImage(100, 100, "#FFFFFF"));
  const page = {
    images: [{
      id: "prototype-flow",
      assetPath: "source.png",
      box: { x: 0, y: 0, w: 100, h: 100 },
      source: {
        detector: "foreground-graphic-crop",
        prototypeValidationFlowObjectified: true,
        prototypeValidationResidualBoxes: [{
          name: "wand-icon",
          box: { x: 20, y: 20, w: 30, h: 30 }
        }],
        layer: { layerType: "diagram-zone" }
      }
    }]
  };

  assert.equal(materializePrototypeValidationResidualCrops(page, dir), true);
  assert.equal(page.images.length, 2);
  assert.equal(page.images[1].id, "prototype-flow-wand-icon");
  assert.equal(page.images[1].source.parentImageId, "prototype-flow");
  assert.equal(page.images[1].source.detector, "prototype-validation-flow-residual-crop");
  assert.equal(page.images[1].source.expressionForm, "icon-or-illustration");
  assert.equal(page.images[1].source.expressionSubtype, "magic-wand");
  assert.equal(page.images[1].source.protectedMinimumUnit, true);
  assert.ok(fs.existsSync(path.join(dir, "source-prototype-validation-wand-icon.png")));
});

