test("createDemandUnderstandingFlowShapes rebuilds output cards and branch connectors", () => {
  const sourceImage = makeImage(960, 540, "#FFFFFF");
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "demand-understanding-lens-"));
  const image = {
    id: "demand-flow",
    box: { x: 36.36, y: 112.88, w: 893.65, h: 310.13 },
    source: {
      detector: "foreground-graphic-underlay-crop",
      layer: {
        layerType: "table-zone",
        recommendedAction: "split-native-with-residual-crop"
      }
    }
  };
  const textBoxes = [
    { text: "会议纪要", box: { x: 95.96, y: 187.5, w: 75.72, h: 20.63 } },
    { text: "旧版说明", box: { x: 203.92, y: 222, w: 74.97, h: 18 } },
    { text: "业务截图", box: { x: 98.96, y: 287.63, w: 76.84, h: 21 } },
    { text: "飞书对话", box: { x: 203.92, y: 328.5, w: 76.84, h: 23.63 } },
    { text: "业务目标", box: { x: 789.82, y: 147.75, w: 77.97, h: 22.88 } },
    { text: "角色关系", box: { x: 789.82, y: 225, w: 76.84, h: 21 } },
    { text: "核心流程", box: { x: 789.82, y: 301.5, w: 76.84, h: 21 } },
    { text: "异常与盲区暴露", box: { x: 761.7, y: 376.88, w: 133.07, h: 21 } }
  ];

  const shapes = createDemandUnderstandingFlowShapes([image], textBoxes, sourceImage, { widthPt: 960, heightPt: 540 }, {
    sourceImage,
    assetDir: tempDir,
    irDir: tempDir,
    deckName: "skills-engine",
    pageIndex: 4
  });

  assert.equal(image.source.demandUnderstandingFlowObjectified, true);
  assert.equal(image.source.componentTemplateFamilyApplied, "process-chain");
  assert.deepEqual(image.source.componentTemplateTargetMotifs, ["lens-funnel-flow", "branch-card-flow", "linear-arrow-chain"]);
  assert.equal(shapes.filter((shape) => shape.source.detector === "demand-understanding-flow-native-card").length, 4);
  assert.equal(shapes.filter((shape) => shape.source.detector === "demand-understanding-flow-native-tab").length, 0);
  assert.equal(shapes.filter((shape) => shape.source.detector === "demand-understanding-flow-native-connector").length, 6);
  assert.equal(shapes.filter((shape) => shape.source.detector === "demand-understanding-flow-native-warning-badge").length, 1);
  assert.equal(shapes.filter((shape) => shape.source.detector === "demand-understanding-flow-native-material-card").length, 4);
  assert.equal(shapes.filter((shape) => shape.source.detector === "demand-understanding-flow-native-material-body-tint").length, 4);
  assert.equal(shapes.filter((shape) => shape.source.detector === "demand-understanding-flow-native-material-header").length, 4);
  assert.equal(shapes.filter((shape) => shape.source.detector === "demand-understanding-flow-native-beam").length, 1);
  assert.equal(shapes.filter((shape) => shape.source.detector === "demand-understanding-flow-native-beam-guide").length, 3);
  assert.ok(shapes.some((shape) => shape.source.detector === "demand-understanding-flow-native-beam" && shape.type === "freeform"));
  assert.equal(shapes.some((shape) => shape.source.detector === "demand-understanding-flow-native-lens"), false);
  assert.equal(shapes.some((shape) => shape.source.detector === "demand-understanding-flow-native-lens-facet"), false);
  assert.equal(shapes.some((shape) => shape.source.detector === "demand-understanding-flow-native-handle"), false);
  assert.equal(shapes.images.length, 1);
  assert.equal(shapes.images[0].source.expressionSubtype, "faceted-gem-magnifier");
  assert.equal(shapes.images[0].source.protectedMinimumUnit, true);
  assert.equal(shapes.images[0].source.intentionalMinimumUnitCrop, true);
  assert.ok(fs.existsSync(path.join(tempDir, shapes.images[0].assetPath)));
  assert.ok(shapes.every((shape) => shape.source.componentTemplateFamilyApplied === "process-chain"));
  assert.ok(shapes.every((shape) => shape.source.componentRenderStrategy?.targetMotifs?.includes("lens-funnel-flow")));
  assert.ok(shapes.every((shape) => shape.source.componentRenderStrategy?.targetMotifs?.includes("branch-card-flow")));
  assert.equal(new Set(shapes.map((shape) => shape.source.nativeComponentGroupId)).size, 11);
  assert.ok(shapes.every((shape) => shape.source.nativeComponentArchetype === "demand-understanding-flow"));
  assert.ok(shapes.every((shape) => shape.source.nativeComponentMinimumUnit === "semantic-component"));
  assert.equal(image.source.demandUnderstandingResidualBoxes.length, 0);
  assert.equal(image.source.dropErasedResidualAfterNativeRebuild, true);
  assert.equal(image.source.objectifiedDemandLensParts, 0);
  assert.equal(image.source.preservedDemandIllustrations, 1);
  assert.deepEqual(image.source.demandUnderstandingNativeTextBoxes.map((item) => item.text), [
    "会议纪要",
    "旧版说明",
    "业务截图",
    "飞书对话",
    "业务目标",
    "角色关系",
    "核心流程",
    "异常与盲区暴露",
    "!"
  ]);
  assert.ok(image.source.demandUnderstandingNativeTextBoxes.every((item) => item.source.layerSourceId === "demand-flow"));
  assert.ok(image.source.demandUnderstandingNativeTextBoxes.every((item) => item.source.nativeComponentGroupId));
  assert.ok(image.source.demandUnderstandingNativeTextBoxes.every((item) => item.source.componentRenderStrategy?.targetMotifs?.includes("lens-funnel-flow")));
  assert.ok(image.source.demandUnderstandingNativeTextBoxes
    .filter((item) => item.source.detector === "demand-understanding-flow-native-material-label")
    .every((item) => item.font.sizePt <= 18.5));
});

test("createDemandUnderstandingFlowShapes lets full semantic evidence override misclassified grid atom strategy", () => {
  const sourceImage = makeImage(960, 540, "#FFFFFF");
  const image = {
    id: "demand-flow-grid-misclassified",
    box: { x: 36.36, y: 112.88, w: 893.65, h: 310.13 },
    source: {
      detector: "foreground-graphic-underlay-crop",
      componentRenderStrategy: {
        mode: "native-visual-atom-rebuild",
        templateFamily: "grid-or-matrix"
      },
      layer: {
        layerType: "table-zone",
        recommendedAction: "attempt-native-reconstruction",
        diagramUnderstanding: {
          archetype: "matrix-or-grid"
        }
      }
    }
  };
  const textBoxes = [
    { text: "会议纪要", box: { x: 95.96, y: 187.5, w: 75.72, h: 20.63 } },
    { text: "旧版说明", box: { x: 203.92, y: 222, w: 74.97, h: 18 } },
    { text: "业务截图", box: { x: 98.96, y: 287.63, w: 76.84, h: 21 } },
    { text: "飞书对话", box: { x: 203.92, y: 328.5, w: 76.84, h: 23.63 } },
    { text: "业务目标", box: { x: 789.82, y: 147.75, w: 77.97, h: 22.88 } },
    { text: "角色关系", box: { x: 789.82, y: 225, w: 76.84, h: 21 } },
    { text: "核心流程", box: { x: 789.82, y: 301.5, w: 76.84, h: 21 } },
    { text: "异常与盲区暴露", box: { x: 761.7, y: 376.88, w: 133.07, h: 21 } }
  ];

  const shapes = createDemandUnderstandingFlowShapes([image], textBoxes, sourceImage, { widthPt: 960, heightPt: 540 });

  assert.equal(image.source.demandUnderstandingFlowObjectified, true);
  assert.equal(shapes.filter((shape) => shape.source.detector === "demand-understanding-flow-native-card").length, 4);
  assert.equal(shapes.some((shape) => shape.source.detector === "demand-understanding-flow-native-lens"), false);
  assert.equal(shapes.filter((shape) => shape.source.detector === "demand-understanding-flow-native-lens-facet").length, 0);
  assert.equal(image.source.preservedDemandIllustrations, 1);
  assert.equal(shapes.filter((shape) => shape.source.detector === "demand-understanding-flow-native-beam-guide").length, 3);
  assert.equal(shapes.filter((shape) => shape.source.detector === "demand-understanding-flow-native-warning-badge").length, 1);
  assert.equal(image.source.componentTemplateFamilyApplied, "process-chain");
});

test("dropDemandUnderstandingResidualCropsWhenNativeCoverage removes wide residuals covered by native demand flow", () => {
  const sourceImage = makeImage(960, 540, "#FFFFFF");
  const image = {
    id: "demand-flow",
    box: { x: 36.36, y: 112.88, w: 893.65, h: 310.13 },
    source: {
      detector: "foreground-graphic-underlay-crop",
      layer: {
        layerType: "table-zone",
        recommendedAction: "split-native-with-residual-crop"
      }
    }
  };
  const textBoxes = [
    { text: "会议纪要", box: { x: 95.96, y: 187.5, w: 75.72, h: 20.63 } },
    { text: "旧版说明", box: { x: 203.92, y: 222, w: 74.97, h: 18 } },
    { text: "业务截图", box: { x: 98.96, y: 287.63, w: 76.84, h: 21 } },
    { text: "飞书对话", box: { x: 203.92, y: 328.5, w: 76.84, h: 23.63 } },
    { text: "业务目标", box: { x: 789.82, y: 147.75, w: 77.97, h: 22.88 } },
    { text: "角色关系", box: { x: 789.82, y: 225, w: 76.84, h: 21 } },
    { text: "核心流程", box: { x: 789.82, y: 301.5, w: 76.84, h: 21 } },
    { text: "异常与盲区暴露", box: { x: 761.7, y: 376.88, w: 133.07, h: 21 } }
  ];
  const shapes = createDemandUnderstandingFlowShapes([image], textBoxes, sourceImage, { widthPt: 960, heightPt: 540 });
  const page = {
    images: [
      {
        id: "demand-flow-split-0",
        box: { x: 58.85, y: 112.88, w: 371.48, h: 307.51 },
        source: {
          detector: "split-wide-residual-crop",
          parentDetector: "foreground-graphic-underlay-crop",
          parentImageId: "demand-flow"
        }
      },
      {
        id: "demand-flow-gem-lens-crop",
        box: { x: 430, y: 186, w: 205, h: 238 },
        source: {
          detector: "demand-understanding-flow-illustration-crop",
          parentDetector: "foreground-graphic-underlay-crop",
          parentImageId: "demand-flow",
          protectedMinimumUnit: true
        }
      },
      {
        id: "unrelated-screenshot",
        box: { x: 20, y: 20, w: 80, h: 50 },
        source: {
          detector: "split-wide-residual-crop",
          parentDetector: "foreground-graphic-crop",
          parentImageId: "other"
        }
      }
    ]
  };

  const dropped = dropDemandUnderstandingResidualCropsWhenNativeCoverage(page, shapes);

  assert.equal(dropped, true);
  assert.deepEqual(page.images.map((item) => item.id), ["demand-flow-gem-lens-crop", "unrelated-screenshot"]);
});

test("arbitrateSpecializedNativeLayerOwnership lets native demand labels own table-zone labels on the same layer", () => {
  const items = [
    {
      text: "业务目标",
      box: { x: 740, y: 134, w: 178, h: 50 },
      source: { detector: "demand-understanding-flow-native-label", layerSourceId: "demand-flow" }
    },
    {
      text: "业务目标",
      box: { x: 790, y: 148, w: 78, h: 23 },
      source: { detector: "table-zone-semantic-native-visible-label", layerSourceId: "demand-flow" }
    },
    {
      text: "业务目标",
      box: { x: 790, y: 148, w: 78, h: 23 },
      source: { detector: "table-zone-semantic-native-visible-label", layerSourceId: "other-flow" }
    }
  ];

  const result = arbitrateSpecializedNativeLayerOwnership(items);

  assert.equal(result.length, 2);
  assert.ok(result.some((item) => item.source.detector === "demand-understanding-flow-native-label"));
  assert.ok(result.some((item) => item.source.layerSourceId === "other-flow"));
});

