test("traditional collaboration breakdown keeps routes native by default and only emits route crops for an explicit fallback", () => {
  const workDir = fs.mkdtempSync(path.join(os.tmpdir(), "traditional-breakdown-route-fidelity-"));
  try {
    const sourceImage = { width: 960, height: 540, rgba: Buffer.alloc(960 * 540 * 4, 255) };
    // This sits inside the first input-to-marker route region, away from all editable text.
    for (let y = 164; y < 167; y += 1) {
      for (let x = 250; x < 430; x += 1) {
        const offset = (y * sourceImage.width + x) * 4;
        sourceImage.rgba[offset] = 150;
        sourceImage.rgba[offset + 1] = 154;
        sourceImage.rgba[offset + 2] = 160;
      }
    }
    const images = [
      { id: "traditional-breakdown-a", box: { x: 114, y: 115, w: 232, h: 105 }, source: { detector: "foreground-graphic-crop" } },
      { id: "traditional-breakdown-b", box: { x: 239, y: 126, w: 635, h: 282 }, source: { detector: "foreground-graphic-crop" } }
    ];
    const result = createTraditionalCollaborationBreakdownObjects(
      { images },
      [{ text: "传统产研协作的系统性断点", box: { x: 261, y: 39, w: 437, h: 36 } }],
      { widthPt: 960, heightPt: 540 },
      { sourceImage, assetDir: path.join(workDir, "assets"), irDir: workDir, deckName: "sample", pageIndex: 1 }
    );

    assert.equal(result.images.length, 0);
    assert.equal(result.shapes.filter((shape) => shape.source.detector === "traditional-collaboration-breakdown-native-link").length, 8);

    const fallback = createTraditionalCollaborationBreakdownObjects(
      { images: images.map((image) => ({ ...image, source: { ...image.source } })) },
      [{ text: "传统产研协作的系统性断点", box: { x: 261, y: 39, w: 437, h: 36 } }],
      { widthPt: 960, heightPt: 540 },
      { sourceImage, assetDir: path.join(workDir, "fallback-assets"), irDir: workDir, deckName: "sample", pageIndex: 1, allowRouteFidelity: true }
    );
    assert.ok(fallback.images.length > 0);
    assert.equal(fallback.shapes.filter((shape) => shape.source.detector === "traditional-collaboration-breakdown-native-link").length, 0);
    assert.ok(fallback.images.every((image) => image.source.textFreeVisualLayer === true));
    assert.ok(fallback.images.every((image) => image.source.intentionalMinimumUnitCrop === true));
  } finally {
    fs.rmSync(workDir, { recursive: true, force: true });
  }
});

test("traditional collaboration breakdown calibrates the four orange markers from source pixels", () => {
  const sourceImage = { width: 960, height: 540, rgba: Buffer.alloc(960 * 540 * 4, 255) };
  const markerBoxes = [[440, 130], [520, 190], [495, 265], [560, 320]];
  for (const [x0, y0] of markerBoxes) {
    for (let y = y0; y < y0 + 60; y += 1) {
      for (let x = x0; x < x0 + 60; x += 1) {
        const offset = (y * sourceImage.width + x) * 4;
        sourceImage.rgba[offset] = 255;
        sourceImage.rgba[offset + 1] = 106;
        sourceImage.rgba[offset + 2] = 0;
      }
    }
  }
  const result = createTraditionalCollaborationBreakdownObjects(
    { images: [{ id: "a", box: { x: 1, y: 1, w: 2, h: 2 }, source: { detector: "foreground-graphic-crop" } }, { id: "b", box: { x: 4, y: 4, w: 2, h: 2 }, source: { detector: "foreground-graphic-crop" } }] },
    [{ text: "传统产研协作的系统性断点", box: { x: 261, y: 39, w: 437, h: 36 } }],
    { widthPt: 960, heightPt: 540 },
    { sourceImage }
  );
  const markers = result.shapes.filter((shape) => shape.source.detector === "traditional-collaboration-breakdown-native-marker");
  assert.deepEqual(markers.map((shape) => shape.box), markerBoxes.map(([x, y]) => ({ x, y, w: 60, h: 60 })));
});

