test("inferBoxFromTextAnchor derives diagram unit boxes from OCR text anchors", () => {
  const variable = inferBoxFromTextAnchor(
    { text: "业务截图", box: { x: 268.77, y: 424.5, w: 74.22, h: 33.75 } },
    { x: 258, y: 430, w: 132, h: 66 },
    {
      padX: 14,
      extraW: 34,
      extraH: 30,
      anchorYRatio: 0.38,
      minW: 118,
      maxW: 146,
      minH: 62,
      maxH: 84,
      minX: 35,
      maxX: 320,
      minY: 145,
      maxY: 430
    }
  );
  assert.deepEqual(variable, { x: 254.77, y: 400.28, w: 118, h: 63.75 });

  const fixed = inferBoxFromTextAnchor(
    { text: "风险遗漏", box: { x: 435.95, y: 424.5, w: 96.71, h: 25.13 } },
    { x: 443, y: 382, w: 150, h: 150 },
    { fixedW: 150, fixedH: 150, padX: 22, padTop: 61, minX: 390, maxX: 455, minY: 140, maxY: 390 }
  );
  assert.deepEqual(fixed, { x: 413.95, y: 363.5, w: 150, h: 150 });

  assert.deepEqual(
    inferBoxFromTextAnchor(null, { x: 10, y: 20, w: 30, h: 40 }, { fixedW: 99 }),
    { x: 10, y: 20, w: 30, h: 40 }
  );
});

