test("createVisualAtomNativeShapes styles high-confidence grid nodes without promoting tiny fragments", () => {
  const image = {
    id: "grid-visual-atoms",
    box: { x: 0, y: 0, w: 400, h: 240 },
    source: {
      layer: {
        layerType: "table-zone",
        diagramUnderstanding: {
          archetype: "matrix-or-grid",
          confidence: 0.92,
          visualAtoms: [{
            id: "main-node",
            kind: "native-rect-candidate",
            nativeCandidate: true,
            box: { x: 20, y: 30, w: 120, h: 48 },
            color: "#3B77C7",
            density: 0.9,
            shapeHint: "rect"
          }, {
            id: "tiny-fragment",
            kind: "native-rect-candidate",
            nativeCandidate: true,
            box: { x: 150, y: 30, w: 8, h: 10 },
            color: "#3B77C7",
            density: 0.9,
            shapeHint: "rect"
          }]
        }
      }
    }
  };

  const shapes = createVisualAtomNativeShapes([image], null, { widthPt: 960, heightPt: 540 });

  const mainNode = shapes.find((shape) => shape.source.atomId === "main-node");
  const tinyFragment = shapes.find((shape) => shape.source.atomId === "tiny-fragment");
  assert.equal(mainNode.style.radiusRatio, 0.11);
  assert.equal(mainNode.style.strokeWidthPt, 0.25);
  assert.ok(mainNode.style.shadow);
  assert.equal(tinyFragment.style.shadow, undefined);
  assert.equal(tinyFragment.style.strokeWidthPt, 0);
});

