test("eraseObjectifiedLayerPrimitives removes native containers and connectors from residual crop assets", () => {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "slideclone-erase-primitives-"));
  const sourceImage = makeImage(420, 220, "#FFFFFF");
  fillRect(sourceImage, 80, 82, 95, 42, "#2D78C4");
  fillRect(sourceImage, 240, 82, 95, 42, "#33A86D");
  fillRect(sourceImage, 175, 101, 65, 4, "#4A4A4A");
  const assetPath = path.join(tempDir, "residual.png");
  writePng(assetPath, cropPng(sourceImage, { x: 50, y: 50, w: 320, h: 120 }));
  const image = {
    id: "diagram-layer",
    assetPath,
    box: { x: 50, y: 50, w: 320, h: 120 },
    source: {
      textObjectified: true,
      layer: {
        layerType: "diagram-zone",
        recommendedAction: "split-native-with-residual-crop"
      }
    }
  };
  const primitiveShapes = [
    {
      id: "left-card",
      type: "roundRect",
      box: { x: 80, y: 82, w: 95, h: 42 },
      source: { detector: "layer-native-container", layerSourceId: "diagram-layer" }
    },
    {
      id: "gap-arrow",
      type: "line",
      box: { x: 175, y: 103, w: 65, h: 0 },
      source: { detector: "layer-native-connector", layerSourceId: "diagram-layer" }
    }
  ];

  eraseObjectifiedLayerPrimitives({
    page: { images: [image] },
    sourceImage,
    textBoxes: [],
    primitiveShapes,
    slideSize: { widthPt: 420, heightPt: 220 },
    irDir: tempDir
  });

  const erased = readPng(assetPath);
  assert.ok(colorDistanceForTest(getPixel(erased, 80 - 50 + 20, 82 - 50 + 20), parseHex("#2D78C4")) > 40);
  assert.ok(colorDistanceForTest(getPixel(erased, 175 - 50 + 25, 103 - 50), parseHex("#4A4A4A")) > 40);
  assert.equal(image.source.primitiveErased, true);
  assert.equal(image.source.erasedPrimitiveCount, 2);
});

