test("splitErasedResidualCrop replaces a large erased diagram crop with smaller residual components", () => {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "slideclone-split-residual-"));
  const residual = makeImage(400, 180, "#FFFFFF");
  fillRect(residual, 35, 40, 80, 58, "#1C74BC");
  fillRect(residual, 260, 70, 90, 60, "#F06A1A");
  const assetPath = path.join(tempDir, "residual.png");
  writePng(assetPath, residual);
  const image = {
    id: "diagram-layer",
    type: "fidelity-crop",
    assetPath,
    box: { x: 100, y: 120, w: 600, h: 270 },
    source: {
      editable: false,
      primitiveErased: true,
      detector: "sparse-diagram-graphic-underlay-crop",
      layer: {
        layerType: "diagram-zone",
        recommendedAction: "split-native-with-residual-crop"
      }
    }
  };

  const split = splitErasedResidualCrop(image, tempDir);

  assert.equal(split.length, 2);
  assert.ok(split.every((item) => item.source.residualSplit === true));
  assert.ok(split.every((item) => item.source.parentImageId === "diagram-layer"));
  assert.ok(split.every((item) => item.box.w < image.box.w * 0.45));
  assert.ok(split.every((item) => item.source.layer.areaRatio < 0.05));
  assert.ok(split.every((item) => item.source.layer.recommendedAction === "preserve-local-crop"));
  assert.ok(fs.existsSync(path.resolve(tempDir, split[0].assetPath)));
});

