test("specialized native hybrid residual erases covered text before writing crop", () => {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "specialized-native-text-erased-"));
  const sourceImage = { width: 960, height: 540, rgba: Buffer.alloc(960 * 540 * 4, 255) };
  for (let y = 120; y < 142; y += 1) {
    for (let x = 140; x < 190; x += 1) {
      const offset = (y * sourceImage.width + x) * 4;
      sourceImage.rgba[offset] = 0;
      sourceImage.rgba[offset + 1] = 0;
      sourceImage.rgba[offset + 2] = 0;
      sourceImage.rgba[offset + 3] = 255;
    }
  }
  const residual = createSpecializedNativeHybridResidualCrop({
    id: "native-graphic-underlay",
    box: { x: 100, y: 90, w: 260, h: 140 },
    source: {
      detector: "specialized-native-shape-bounds",
      expressionForm: "complex-diagram",
      expressionSubtype: "stacked-architecture",
      stackedArchitectureObjectified: true
    }
  }, {
    hybridComponentTemplateResiduals: true,
    sourceImage,
    assetDir: tmp,
    irDir: tmp,
    slideSize: { widthPt: 960, heightPt: 540 },
    deckName: "Deck_A",
    pageIndex: 0,
    residualKind: "stacked-architecture",
    eraseSpecializedHybridResidualText: true,
    textBoxes: [
      { text: "Editable label", box: { x: 136, y: 116, w: 60, h: 30 } }
    ]
  });

  assert.equal(residual.source.textErasedFromCrop, true);
  assert.equal(residual.source.erasedTextBoxCount, 1);
  const erased = readPng(path.join(tmp, residual.assetPath));
  const sampleOffset = (32 * erased.width + 48) * 4;
  assert.ok(erased.rgba[sampleOffset] > 220);
  assert.ok(erased.rgba[sampleOffset + 1] > 220);
  assert.ok(erased.rgba[sampleOffset + 2] > 220);
});

