test("system map diagrams rebuild dense product brain maps as native nodes and grids", () => {
  const image = {
    id: "native-graphic-line-diagram-underlay",
    box: { x: 34.49, y: 139.13, w: 890.28, h: 374.63 },
    source: {
      detector: "line-diagram-graphic-underlay-crop",
      nonEditableReason: "dense-line-diagram-preserved-as-movable-crop",
      layer: {
        layerType: "diagram-zone",
        diagramUnderstanding: { archetype: "unclassified-diagram" }
      }
    }
  };
  const textBoxes = [
    { text: "终局视野：生生不息的企业级数字化产品大脑", box: { x: 31, y: 34, w: 460, h: 35 } },
    { text: "多域资产全景搜素.", box: { x: 755, y: 40, w: 160, h: 18 } },
    { text: "让每一次交付都沉淀为企业级Hub大门户中的知识复利。", box: { x: 33, y: 82, w: 430, h: 20 } },
    { text: "产品版图（SystemMap）", box: { x: 404, y: 121, w: 165, h: 19 } }
  ];

  const result = createSystemMapDiagramObjects([image], textBoxes, { widthPt: 960, heightPt: 540 });
  assert.equal(image.source.systemMapDiagramObjectified, true);
  assert.equal(image.source.dropErasedResidualAfterNativeRebuild, true);
  const backgroundDots = result.shapes.filter((shape) => shape.source?.detector === "system-map-native-background-dot");
  assert.ok(backgroundDots.length <= 36);
  assert.ok(backgroundDots.every((shape) => shape.source?.decorativeTexture === true));
  assert.ok(backgroundDots.every((shape) => shape.source?.minimumUnitPolicy === "sampled-decorative-texture"));
  const assetGridRows = result.shapes.filter((shape) => shape.source?.detector === "system-map-native-asset-grid");
  assert.equal(assetGridRows.length, 18);
  assert.ok(assetGridRows.every((shape) => shape.type === "freeform"));
  assert.ok(assetGridRows.every((shape) => shape.source?.decorativeTexture === true));
  assert.ok(assetGridRows.every((shape) => shape.source?.minimumUnitPolicy === "source-sampled-asset-grid-tile-run"));
  assert.equal(assetGridRows.reduce((count, shape) => count + shape.source.tileCount, 0), 333);
  assert.ok(assetGridRows.every((shape) => shape.style.freeformSegments.length <= 100));
  assert.ok(result.shapes.filter((shape) => shape.source?.detector === "system-map-native-mapping-line").length >= 80);
  const assetGridBoxes = result.shapes
    .filter((shape) => shape.source?.detector === "system-map-native-asset-grid")
    .map((shape) => shape.box);
  const assetGridBounds = {
    x: Math.min(...assetGridBoxes.map((box) => box.x)),
    y: Math.min(...assetGridBoxes.map((box) => box.y)),
    w: Math.max(...assetGridBoxes.map((box) => box.x + box.w)) - Math.min(...assetGridBoxes.map((box) => box.x)),
    h: Math.max(...assetGridBoxes.map((box) => box.y + box.h)) - Math.min(...assetGridBoxes.map((box) => box.y))
  };
  assert.ok(assetGridBounds.x <= 40);
  assert.ok(assetGridBounds.y >= 485);
  assert.ok(assetGridBounds.w >= 875);
  assert.ok(assetGridBounds.h <= 28);
  const searchBox = result.shapes.find((shape) => shape.id.endsWith("-native-search-box"));
  assert.ok(searchBox);
  assert.ok(searchBox.box.x >= 700 && searchBox.box.x <= 704);
  assert.ok(searchBox.box.y >= 31 && searchBox.box.y <= 34);
  assert.ok(searchBox.box.w >= 220);
  const bottomLabels = result.textBoxes.filter((textBox) => textBox.source?.detector === "system-map-native-label");
  assert.equal(bottomLabels.length, 4);
  assert.ok(bottomLabels.every((textBox) => textBox.box.y > assetGridBounds.y + assetGridBounds.h));
  assert.ok(result.shapes.filter((shape) => shape.source?.detector === "system-map-native-network-node").length >= 30);
  const networkEdges = result.shapes.filter((shape) => shape.source?.detector === "system-map-native-network-edge");
  assert.ok(networkEdges.length >= 80);
  assert.ok(networkEdges.every((shape) => shape.source?.route === "orthogonal"));
  assert.ok(networkEdges.every((shape) => Math.abs(Number(shape.box?.w || 0)) < 0.1 || Math.abs(Number(shape.box?.h || 0)) < 0.1));
  assert.ok(result.shapes.filter((shape) => shape.source?.detector === "system-map-native-network-detail-node").length >= 18);
  const detailEdges = result.shapes.filter((shape) => shape.source?.detector === "system-map-native-network-detail-edge");
  assert.ok(detailEdges.length >= 24);
  assert.ok(detailEdges.every((shape) => shape.source?.route === "orthogonal"));
  assert.ok(detailEdges.every((shape) => Math.abs(Number(shape.box?.w || 0)) < 0.1 || Math.abs(Number(shape.box?.h || 0)) < 0.1));
  assert.ok(result.shapes.filter((shape) => shape.source?.detector === "system-map-native-network-rail-module").length >= 14);
  assert.ok(result.shapes.some((shape) => shape.source?.detector === "system-map-native-search"));
  assert.ok(result.textBoxes.some((textBox) => textBox.text === "物流域"));
  assert.ok(result.textBoxes.some((textBox) => textBox.source?.detector === "system-map-native-network-rail-label"));
  assert.equal(result.shapes.every((shape) => Number.isFinite(shape.box?.x) && Number.isFinite(shape.box?.y)), true);
  assert.equal(result.textBoxes.every((textBox) => textBox.id), true);
});

