test("system map diagrams detect native detail nodes from source image pixels", () => {
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "system-map-source-detect-"));
  const sourceImageFile = path.join(tmpDir, "source.png");
  const sourceImage = {
    width: 960,
    height: 540,
    rgba: Buffer.alloc(960 * 540 * 4, 255)
  };
  const drawBlueBox = (cx, cy, size = 12) => {
    const half = Math.floor(size / 2);
    for (let y = cy - half; y <= cy + half; y += 1) {
      for (let x = cx - half; x <= cx + half; x += 1) {
        const offset = (y * sourceImage.width + x) * 4;
        sourceImage.rgba[offset] = 18;
        sourceImage.rgba[offset + 1] = 108;
        sourceImage.rgba[offset + 2] = 180;
        sourceImage.rgba[offset + 3] = 255;
      }
    }
  };
  const image = {
    id: "native-graphic-line-diagram-underlay",
    box: { x: 34.49, y: 139.13, w: 890.28, h: 374.63 },
    source: {
      detector: "line-diagram-graphic-underlay-crop",
      nonEditableReason: "dense-line-diagram-preserved-as-movable-crop",
      layer: { layerType: "diagram-zone" }
    }
  };
  const centers = [
    [405, 195], [450, 195], [495, 195],
    [405, 245], [450, 245], [495, 245],
    [405, 295], [450, 295], [495, 295],
    [405, 345], [450, 345], [495, 345]
  ];
  centers.forEach(([x, y]) => drawBlueBox(x, y));
  writePng(sourceImageFile, sourceImage);
  const textBoxes = [
    { text: "终局视野：生生不息的企业级数字化产品大脑", box: { x: 31, y: 34, w: 460, h: 35 }, source: { pageImage: sourceImageFile } },
    { text: "多域资产全景搜素.", box: { x: 755, y: 40, w: 160, h: 18 }, source: { pageImage: sourceImageFile } },
    { text: "产品版图（SystemMap）", box: { x: 404, y: 121, w: 165, h: 19 }, source: { pageImage: sourceImageFile } }
  ];

  const result = createSystemMapDiagramObjects([image], textBoxes, { widthPt: 960, heightPt: 540 });
  const detectedNodes = result.shapes.filter((shape) =>
    shape.source?.detector === "system-map-native-network-detail-node" && shape.source?.sourceImageDetected === true
  );
  const detectedEdges = result.shapes.filter((shape) =>
    shape.source?.detector === "system-map-native-network-detail-edge" && shape.source?.sourceImageDetected === true
  );

  assert.ok(detectedNodes.length >= 12);
  assert.ok(detectedEdges.length >= 12);
  assert.equal(result.shapes.some((shape) => shape.id.includes("detail-node-detected")), true);
});

